window.RECIPES = [{"slug": "cheesecake.html", "title": "Карамельно-сливочный ПП-чизкейк с лимонной ноткой", "shortTitle": "Карамельно-сливочный ПП-чизкейк", "description": "Нежнейшая кремовая текстура сливочного пломбира, аромат сгущенного молока, благородная цитрусовая кислинка и рекордное содержание протеина для сушки и набора сухой мышечной массы.", "image": "cheesecake.png", "time": "26–28 минут", "difficulty": "Простая", "tags": ["Высокобелковое"], "category": "Десерты", "defaultVariant": 6, "variants": [{"id": 1, "name": "С лимонной ноткой", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "20 минут"}, {"label": "Температура", "value": "170°C"}, {"label": "Порций", "value": "4 порции"}, {"label": "Готовый вес", "value": "~740 грамм"}], "total": {"label": "На весь чизкейк Вес ~740 г", "kcal": 1107.0, "macros": [{"label": "Белки", "value": 125.8}, {"label": "Жиры", "value": 20.1}, {"label": "Углеводы", "value": 90.6}, {"label": "Клетчатка", "value": 13.0}]}, "per100": {"label": "На 100 г готового Эталон", "kcal": 150.0, "macros": [{"label": "Белки", "value": 17.0}, {"label": "Жиры", "value": 2.7}, {"label": "Углеводы", "value": 12.2}, {"label": "Клетчатка", "value": 1.8}]}, "ingredients": [{"name": "Творог в брикете (0.1–2%)", "amount": "400 г (2 пачки)"}, {"name": "Греческий йогурт или мягкий творог (0.1–2.5%)", "amount": "120 г (1 шт)"}, {"name": "Яйца куриные С0", "amount": "2 шт (~125 г)"}, {"name": "Протеин КСБ-80 (без вкуса)", "amount": "30 г (1 скуп)"}, {"name": "Сгущенное молоко 1%", "amount": "120 г (1/3 банки)"}, {"name": "Лимонный сок свежевыжатый", "amount": "1 ст. л. (~15 г)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "5 стиков"}, {"name": "Псиллиум (шелуха подорожника)", "amount": "3 ч. л. с горкой (~15 г)"}, {"name": "Соль мелкая", "amount": "Щепотка"}], "steps": [{"title": "Жидкая основа и база", "html": "<div class=\"step-content\">\n<p>В чашу блендера поместите творог (400 г), греческий йогурт или мягкий творожок (120 г), 2 яйца С0, 120 г сгущенки 1% (1/3 банки) и 1 ст. л. сока лимона.</p>\n</div>"}, {"title": "Взбивание до крема", "html": "<div class=\"step-content\">\n<p>Добавьте протеин (30 г), 5 стиков ФитПарада и щепотку соли. Пробейте погружным блендером 1.5–2 минуты до абсолютно гладкого, шелковистого глянцевого состояния без комочков.</p>\n</div>"}, {"title": "Введение псиллиума и отдых", "html": "<div class=\"step-content\">\n<p>Всыпьте 3 ч. л. псиллиума, перемешайте лопаткой и <strong>оставьте на 5–7 минут</strong>. Псиллиум впитает лишнюю влагу, связав протеин и стабилизировав тесто.</p>\n</div>"}, {"title": "Выпекание в аэрогриле", "html": "<div class=\"step-content\">\n<p>Форму (диаметр 16–18 см) застелите пергаментом, вылейте тесто и разровняйте. Выпекайте при <strong>170°C в течение 20 минут</strong> до карамельной корочки.</p>\n</div>"}, {"title": "Охлаждение (Секрет текстуры!)", "html": "<div class=\"step-content\">\n<p>Остудите чизкейк до комнатной температуры, затем уберите в холодильник на 2–3 часа (или на ночь). Холодным он станет плотным, как оригинальный ресторанный чизкейк.</p>\n</div>"}]}, {"id": 2, "name": "Греческий Teos + Красная цена", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "22–24 минуты"}, {"label": "Температура", "value": "165–170°C"}, {"label": "Порций", "value": "4 порции"}, {"label": "Готовый вес", "value": "~800 грамм"}], "total": {"label": "На весь чизкейк Вес ~800 г", "kcal": 1165.0, "macros": [{"label": "Белки", "value": 131.2}, {"label": "Жиры", "value": 21.2}, {"label": "Углеводы", "value": 99.5}, {"label": "Клетчатка", "value": 14.0}]}, "per100": {"label": "На 100 г готового Супер-пышный ⭐", "kcal": 146.0, "macros": [{"label": "Белки", "value": 16.4}, {"label": "Жиры", "value": 2.7}, {"label": "Углеводы", "value": 12.4}, {"label": "Клетчатка", "value": 1.8}]}, "ingredients": [{"name": "Творог обезжиренный («Красная цена» 0%)", "amount": "360 г (2 пачки по 180 г)"}, {"name": "Греческий йогурт «Савушкин Teos» 2%", "amount": "250 г (1 банка) — секрет пышности!"}, {"name": "Яйца куриные С0", "amount": "2 шт (~125 г)"}, {"name": "Сывороточный протеин (ваниль/без вкуса)", "amount": "30 г (1 скуп)"}, {"name": "Сгущенное молоко 1%", "amount": "140 г (чуть больше)"}, {"name": "Псиллиум (шелуха подорожника)", "amount": "3.5–4 ч. л. (~18 г)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "5–6 стиков"}, {"name": "Соль мелкая", "amount": "щепотка"}], "steps": [{"title": "Творожная основа и сгущенка", "html": "<div class=\"step-content\">\n<p>В чашу блендера поместите 2 пачки творога «Красная цена» (360 г), 1 банку натурального греческого йогурта «Савушкин Teos 2%» (250 г), разбейте 2 яйца С0 и влейте 140 г сгущенки 1%.</p>\n</div>"}, {"title": "Взбивание до шелковистого мусса", "html": "<div class=\"step-content\">\n<p>Добавьте 30 г протеина, 5–6 стиков ФитПарада и щепотку соли (она выделит сливочный пломбирный вкус). Тщательно пробейте погружным блендером 2 минуты до глянцевого однородного крема без комочков.</p>\n</div>"}, {"title": "Введение псиллиума и отдых (Важно!)", "html": "<div class=\"step-content\">\n<p>Всыпьте 3.5–4 ч. л. псиллиума (~18 г), перемешайте силиконовой лопаткой и <strong>дайте постоять 7–10 минут</strong>. Сквашенная структура греческого йогурта в сочетании с псиллиумом удерживает пузырьки воздуха и обеспечивает равномерный, невероятно пышный подъем при выпекании.</p>\n</div>"}, {"title": "Выпекание в аэрогриле", "html": "<div class=\"step-content\">\n<p>Форму (диаметр 16–18 см) застелите пергаментом, вылейте тесто и разровняйте. Выпекайте при <strong>165–170°C в течение 22–24 минут</strong> до аппетитной карамельной корочки.</p>\n</div>"}, {"title": "Холодная стабилизация", "html": "<div class=\"step-content\">\n<p>Остудите чизкейк до комнатной температуры прямо в форме, а затем <strong>уберите в холодильник минимум на 3–4 часа (или на ночь)</strong>. Благодаря греческому йогурту Teos чизкейк получается заметно пышнее и выше, напоминая воздушное сливочное пломбирное суфле!</p>\n</div>"}]}, {"id": 3, "name": "Ирбитский 0% + Простоквашино 5%", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "28–30 минут"}, {"label": "Температура", "value": "155–160°C"}, {"label": "Порций", "value": "4–6 порций"}, {"label": "Готовый вес", "value": "~615 грамм"}], "total": {"label": "На весь чизкейк Вес ~615 г", "kcal": 1036.0, "macros": [{"label": "Белки", "value": 111.5}, {"label": "Жиры", "value": 24.5}, {"label": "Углеводы", "value": 88.0}, {"label": "Клетчатка", "value": 8.5}]}, "per100": {"label": "На 100 г готового Крем-пломбир 🔥", "kcal": 168.0, "macros": [{"label": "Белки", "value": 18.1}, {"label": "Жиры", "value": 4.0}, {"label": "Углеводы", "value": 14.3}, {"label": "Клетчатка", "value": 1.4}]}, "ingredients": [{"name": "Творог «Ирбитский» обезжиренный", "amount": "200 г (1 пачка)"}, {"name": "Творог мягкий «Простоквашино» 5%", "amount": "170 г (1 стаканчик)"}, {"name": "Сгущенное молоко 1%", "amount": "130 г"}, {"name": "Яйца куриные С0", "amount": "2 шт (~120 г)"}, {"name": "Сывороточный протеин (без вкуса / КСБ 80)", "amount": "45 г (1.5 скупа)"}, {"name": "Псиллиум (шелуха подорожника)", "amount": "10–12 г (2.5 ч. л.) — стабильность дна"}, {"name": "Ванилин-интенсив Dr. Bakers", "amount": "1–2 г (насыщенный пломбирный аромат)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "5–6 стиков"}, {"name": "Разрыхлитель теста", "amount": "1/2 ч. л. (~3 г)"}, {"name": "Соль мелкая", "amount": "щепотка"}], "steps": [{"title": "Творожная основа и сгущенка", "html": "<div class=\"step-content\">\n<p>В чашу блендера поместите <strong>200 г творога «Ирбитский 0%»</strong> и <strong>170 г мягкого творога «Простоквашино 5%»</strong>. Разбейте <strong>2 яйца С0</strong> и влейте <strong>130 г сгущенки 1%</strong>. Пробейте погружным блендером 1 минуту до гладкого однородного крема без крупинок.</p>\n</div>"}, {"title": "Протеин, ванилин-интенсив и подсластитель", "html": "<div class=\"step-content\">\n<p>Добавьте <strong>45 г протеина без добавок</strong>, <strong>1–2 г ванилина-интенсив Dr. Bakers</strong> <em>(дает мощный пломбирный букет без горечи)</em>, <strong>5–6 стиков ФитПарада</strong>, 1/2 ч. л. разрыхлителя и щепотку соли. Тщательно пробейте блендером 1–2 минуты.</p>\n</div>"}, {"title": "Введение псиллиума и отдых (5–7 минут)", "html": "<div class=\"step-content\">\n<p>Всыпьте <strong>10–12 г псиллиума (2.5 ч. л.)</strong> и аккуратно перемешайте силиконовой лопаткой. <strong>Дайте постоять 5–7 минут при комнатной температуре</strong> — псиллиум свяжет свободную влагу из мягкого творога и сделает крем густым и послушным без муки.</p>\n</div>"}, {"title": "Выпекание в аэрогриле (155–160°C, 28–30 мин)", "html": "<div class=\"step-content\">\n<p>Форму диаметром 16–18 см застелите пергаментом или смажьте каплей масла. Перелейте массу и разровняйте. Благодаря умеренной высоте слоя и мягкой температуре <strong>155–160°C за 28–30 минут</strong> десерт равномерно пропекается до самого дна, не оставляя сырой сердцевины!</p>\n</div>"}, {"title": "Охлаждение и стабилизация", "html": "<div class=\"step-content\">\n<p>Оставьте на 15 минут в выключенном аэрогриле с приоткрытой чашей, затем остудите при комнатной температуре и <strong>уберите в холодильник минимум на 3–4 часа (лучше на ночь)</strong>. Псиллиум и казеин мягкого творога создадут плотную, тающую текстуру настоящего сливочного пломбира!</p>\n</div>"}]}, {"id": 4, "name": "3 белка (без взбивания) + Моя цена 5%", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "30–33 минуты"}, {"label": "Температура", "value": "155°C"}, {"label": "Порций", "value": "4–6 порций"}, {"label": "Готовый вес", "value": "~725 грамм"}], "total": {"label": "На весь чизкейк Вес ~725 г", "kcal": 1177.0, "macros": [{"label": "Белки", "value": 127.1}, {"label": "Жиры", "value": 30.8}, {"label": "Углеводы", "value": 95.1}, {"label": "Клетчатка", "value": 8.8}]}, "per100": {"label": "На 100 г готового Белковый пломбир ⭐", "kcal": 162.0, "macros": [{"label": "Белки", "value": 17.5}, {"label": "Жиры", "value": 4.2}, {"label": "Углеводы", "value": 13.1}, {"label": "Клетчатка", "value": 1.2}]}, "ingredients": [{"name": "Творог «Моя цена» 5%", "amount": "360 г (2 пачки по 180 г)"}, {"name": "Творог мягкий «Простоквашино» 5%", "amount": "170 г (1 стаканчик)"}, {"name": "Сгущенное молоко с сахаром 1%", "amount": "130 г (~1/3 банки)"}, {"name": "Сывороточный протеин (без вкуса / КСБ 80)", "amount": "45 г (1.5 скупа)"}, {"name": "Яичные белки С0 (без желтков)", "amount": "3 шт (~105 г) — сразу в блендер"}, {"name": "Псиллиум (шелуха подорожника)", "amount": "8–10 г (2 ч. л.) — стабильность дна"}, {"name": "Ванилин-интенсив Dr. Bakers", "amount": "1–2 г (насыщенный пломбир)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "7 стиков"}, {"name": "Разрыхлитель теста", "amount": "1/2 ч. л. (~3 г)"}, {"name": "Соль мелкая", "amount": "щепотка"}], "steps": [{"title": "Творожная основа и белки в блендер", "html": "<div class=\"step-content\">\n<p>В чашу блендера поместите <strong>360 г творога «Моя цена 5%»</strong>, <strong>170 г мягкого «Простоквашино 5%»</strong>, отделите и добавьте <strong>3 яичных белка С0</strong> (желтки не понадобятся, взбивать миксером ничего не нужно!), влейте <strong>130 г сгущенки 1%</strong>. Пробейте погружным блендером 1 минуту до гладкого крема без крупинок.</p>\n</div>"}, {"title": "Протеин, ванилин-интенсив и подсластитель", "html": "<div class=\"step-content\">\n<p>Добавьте <strong>45 г протеина без вкуса</strong>, <strong>1–2 г ванилина Dr. Bakers</strong>, <strong>7 стиков ФитПарада</strong>, 1/2 ч. л. разрыхлителя и щепотку соли. Тщательно пробейте погружным блендером 1–1.5 минуты до шелковистого глянцевого состояния.</p>\n</div>"}, {"title": "Введение псиллиума и отдых (5–7 минут)", "html": "<div class=\"step-content\">\n<p>Всыпьте <strong>2 ч. л. псиллиума (8–10 г)</strong> и аккуратно перемешайте силиконовой лопаткой. <strong>Дайте постоять 5–7 минут при комнатной температуре</strong> — псиллиум равномерно свяжет свободную влагу белков и мягкого творога, обеспечив плотную кремовую структуру и сухое дно без сырости.</p>\n</div>"}, {"title": "Выпекание в аэрогриле (155°C, 30–33 мин)", "html": "<div class=\"step-content\">\n<p>Форму диаметром 16–18 см застелите пергаментом, перелейте крем и разровняйте. Выпекайте при температуре <strong>155°C в течение 30–33 минут</strong>. Края должны уверенно схватиться и слегка отойти от стенок формы, а самый центр — нежно подрагивать.</p>\n</div>"}, {"title": "Остывание и стабилизация в холоде", "html": "<div class=\"step-content\">\n<p>Оставьте на 15 минут в выключенном аэрогриле с приоткрытой чашей, затем остудите при комнатной температуре и <strong>уберите в холодильник минимум на 4–5 часов (лучше на ночь)</strong>. Текстура превратится в плотный, тающий сливочный пломбир в стиле классического чизкейка «Нью-Йорк»!</p>\n</div>"}]}, {"id": 5, "name": "Першино 5% + Ирбитский 0% + Савушкин 0.1%", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "26–28 минут"}, {"label": "Температура", "value": "160–165°C"}, {"label": "Порций", "value": "4–6 порций"}, {"label": "Готовый вес", "value": "~730 грамм"}], "total": {"label": "На весь чизкейк Вес ~730 г", "kcal": 1037.0, "macros": [{"label": "Белки", "value": 140.4}, {"label": "Жиры", "value": 28.2}, {"label": "Углеводы", "value": 51.2}, {"label": "Клетчатка", "value": 9.8}]}, "per100": {"label": "На 100 г готового Идеальный баланс 🔥", "kcal": 142.0, "macros": [{"label": "Белки", "value": 19.2}, {"label": "Жиры", "value": 3.9}, {"label": "Углеводы", "value": 7.0}, {"label": "Клетчатка", "value": 1.4}]}, "ingredients": [{"name": "Творог «Першино» 5%", "amount": "220 г"}, {"name": "Творог «Ирбитский» обезжиренный", "amount": "200 г (1 брикет)"}, {"name": "Творог мягкий «Савушкин» 0.1%", "amount": "125 г (1 стаканчик)"}, {"name": "Сгущенное молоко с сахаром 1%", "amount": "120 г (~1/3 банки)"}, {"name": "Яйца куриные С0 (целиком)", "amount": "2 шт (~115 г)"}, {"name": "Сывороточный протеин (КСБ 80 / без вкуса)", "amount": "45 г (1.5 скупа)"}, {"name": "Псиллиум (шелуха подорожника)", "amount": "10 г (~2.5 ч. л.) — фиксация влаги"}, {"name": "Лимонная кислота", "amount": "1/4 ч. л. (в 1 ч. л. воды) — баланс вкуса"}, {"name": "Заменитель сахара (ФитПарад №7/10)", "amount": "7 стиков"}, {"name": "Ванилин-интенсив Dr. Bakers", "amount": "1–2 г (пломбирный аромат)"}, {"name": "Разрыхлитель теста", "amount": "1/2 ч. л. (~3 г)"}, {"name": "Соль мелкая", "amount": "щепотка"}], "steps": [{"title": "Жидкая эмульсия и баланс кислоты", "html": "<div class=\"step-content\">\n<p>В чашу блендера выложите <strong>125 г мягкого творога «Савушкин»</strong>, разбейте <strong>2 яйца С0 целиком</strong>, добавьте <strong>120 г сгущенки 1%</strong> и <strong>1/4 ч. л. лимонной кислоты</strong>, предварительно растворенной в 1 чайной ложке теплой воды. Пробейте блендером 20–30 секунд до гладкой жидкой эмульсии.</p>\n</div>"}, {"title": "Введение плотного творога в крем", "html": "<div class=\"step-content\">\n<p>Добавьте <strong>220 г творога «Першино» 5%</strong> и <strong>200 г творога «Ирбитский» 0%</strong>. Тщательно пробейте погружным блендером 1.5–2 минуты до абсолютно гладкого, шелковистого крема без единой крупинки творога.</p>\n</div>"}, {"title": "Протеин, ванилин и ФитПарад", "html": "<div class=\"step-content\">\n<p>Всыпьте <strong>45 г протеина КСБ 80</strong>, <strong>7 стиков ФитПарада</strong>, <strong>1–2 г ванилина Dr. Bakers</strong>, 1/2 ч. л. разрыхлителя и щепотку соли. Пробейте погружным блендером еще 30–40 секунд до глянцевого состояния.</p>\n</div>"}, {"title": "Псиллиум и стабилизация массы (5–7 мин)", "html": "<div class=\"step-content\">\n<p>Всыпьте <strong>10 г псиллиума (~2.5 ч. л.)</strong> и аккуратно вмешайте силиконовой лопаткой. Оставьте массу постоять <strong>5–7 минут</strong> при комнатной температуре: псиллиум раскроется, свяжет лишнюю влагу творога и гарантирует монолитное сухое дно.</p>\n</div>"}, {"title": "Выпекание в аэрогриле (160–165°C, 26–28 мин)", "html": "<div class=\"step-content\">\n<p>Перелейте массу в форму 16–18 см (силиконовую или застеленную качественным пергаментом) и разровняйте. Выпекайте при температуре <strong>160–165°C в течение 26–28 минут</strong>. Края должны схватиться и аппетитно подрумяниться, а серединка — нежно колыхаться при покачивании формы.</p>\n</div>"}, {"title": "Остывание и выдержка в холоде", "html": "<div class=\"step-content\">\n<p>Оставьте на 15–20 минут в выключенном аэрогриле с приоткрытой корзиной, затем остудите до комнатной температуры и <strong>уберите в холодильник минимум на 4–5 часов (или на ночь)</strong>. Текстура превратится в тающий плотный пломбир!</p>\n</div>"}]}, {"id": 6, "name": "Карамельный крем-брюле (Вареная сгущенка)", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "26–28 минут"}, {"label": "Температура", "value": "160°C"}, {"label": "Порций", "value": "4 порции"}, {"label": "Готовый вес", "value": "~725 грамм"}], "total": {"label": "На весь чизкейк Вес ~725 г", "kcal": 1047.0, "macros": [{"label": "Белки", "value": 118.3}, {"label": "Жиры", "value": 27.1}, {"label": "Углеводы", "value": 79.3}, {"label": "Клетчатка", "value": 8.8}]}, "per100": {"label": "На 100 г готового Крем-брюле 🔥", "kcal": 145.0, "macros": [{"label": "Белки", "value": 16.3}, {"label": "Жиры", "value": 3.7}, {"label": "Углеводы", "value": 10.9}, {"label": "Клетчатка", "value": 1.2}]}, "ingredients": [{"name": "Творог «Красная цена» обезжиренный 0%", "amount": "360 г (2 пачки по 180 г)"}, {"name": "Творог мягкий «Савушкин» 0.1%", "amount": "125 г (1 стаканчик)"}, {"name": "Сгущенка вареная «Станция Молочная» 4%", "amount": "120 г (густая карамельная база)"}, {"name": "Яйца куриные С0 (целиком)", "amount": "3 шт (~170 г) — сочность и нежность"}, {"name": "Сывороточный протеин (КСБ 80 / без вкуса)", "amount": "45 г (1.5 скупа)"}, {"name": "Псиллиум (шелуха подорожника)", "amount": "10 г (~2.5 ч. л.) — стабильность основы"}, {"name": "Лимонная кислота", "amount": "1/4 ч. л. (в 1 ч. л. воды) — снять приторность"}, {"name": "Заменитель сахара (ФитПарад №7/10)", "amount": "7 стиков (насыщенная десертная сладость)"}, {"name": "Ванилин-интенсив Dr. Bakers", "amount": "1–2 г"}, {"name": "Разрыхлитель теста", "amount": "1/2 ч. л. (~3 г)"}, {"name": "Соль мелкая", "amount": "щепотка (усиливает карамель)"}], "steps": [{"title": "Карамельная жидкая эмульсия", "html": "<div class=\"step-content\">\n<p>В чашу блендера отправьте <strong>125 г мягкого творога «Савушкин»</strong>, <strong>3 яйца С0 целиком</strong>, <strong>120 г вареной сгущенки 4%</strong>, <strong>7 стиков ФитПарада</strong>, ванилин, щепотку соли и <strong>1/4 ч. л. лимонной кислоты</strong> (предварительно растворенной в 1 ч. л. теплой воды). Пробейте погружным блендером 30 секунд до однородного карамельного крема.</p>\n</div>"}, {"title": "Введение творога «Красная цена»", "html": "<div class=\"step-content\">\n<p>Добавьте <strong>2 пачки творога «Красная цена» 0% (360 г)</strong>. Тщательно пробейте погружным блендером 1.5–2 минуты. Масса должна стать шелковистой, глянцевой, красивого цвета топленого молока без творожных крупинок.</p>\n</div>"}, {"title": "Протеин и разрыхлитель", "html": "<div class=\"step-content\">\n<p>Всыпьте <strong>45 г протеина КСБ 80</strong> и 1/2 ч. л. разрыхлителя. Пробейте блендером еще 30 секунд до полного растворения сухих компонентов.</p>\n</div>"}, {"title": "Псиллиум и гидратация (5–7 минут)", "html": "<div class=\"step-content\">\n<p>Всыпьте <strong>10 г псиллиума (~2.5 ч. л.)</strong> и аккуратно перемешайте силиконовой лопаткой. <strong>Оставьте постоять 5–7 минут</strong> при комнатной температуре. Псиллиум свяжет влагу обезжиренного творога и гарантирует монолитное сухое дно.</p>\n</div>"}, {"title": "Выпекание в аэрогриле (160°C, 25–28 мин)", "html": "<div class=\"step-content\">\n<p>Форму 16–18 см застелите пергаментом или смажьте каплей масла. Перелейте карамельную массу. Выпекайте при температуре <strong>160°C в течение 25–28 минут</strong>. Из-за карамелизации сахаров варенки верхушка красиво подрумянится, а центр должен слегка подрагивать при покачивании.</p>\n</div>"}, {"title": "Остывание и выдержка в холоде", "html": "<div class=\"step-content\">\n<p>Оставьте на 15–20 минут в выключенном аэрогриле с приоткрытой чашей. Затем остудите при комнатной температуре и <strong>уберите в холодильник минимум на 4–5 часов (лучше на ночь)</strong>. Текстура станет нежной и плотной, как классический торт крем-брюле!</p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card var-view var-1-view\">\n<h3>💡 Секреты идеального результата (Вариация 1)</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🍋 Лимонный сок</strong>\n<p>Реагирует с молочным белком, укрепляя структуру чизкейка, и убирает приторность сгущенки.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🌾 Псиллиум — сила клетчатки</strong>\n<p>13 г чистой клетчатки на пирог удерживают форму без грамма муки и продлевают сытость на 4+ часа.</p>\n</div>\n<div class=\"tip-box\">\n<strong>❄️ Холод раскрывает вкус</strong>\n<p>В теплом виде чизкейк нежный, как суфле, а после холодильника приобретает классическую плотную текстуру «Нью-Йорк».</p>\n</div>\n</div>\n</div><div class=\"tips-card var-view var-2-view\">\n<h3>💡 Секреты идеального результата (Вариация 2)</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>✨ Секрет пышности — греческий Teos</strong>\n<p>В отличие от обычного пастообразного мягкого творога, густой сквашенный йогурт Teos при выпекании придает десерту потрясающую пышность, легкость и воздушную пористость.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🌾 Роль псиллиума (3.5–4 ч. л.)</strong>\n<p>В сочетании с греческим йогуртом псиллиум удерживает структуру суфле и влагу, обеспечивая высокий ровный срез чизкейка без опадания.</p>\n</div>\n<div class=\"tip-box\">\n<strong>💪 131 г чистого белка</strong>\n<p>В этой вариации 610 г чистейшей молочно-белковой основы: почти 33 г белка на порцию и всего 146 ккал на 100 г — идеальный макронутриентный профиль!</p>\n</div>\n</div>\n</div><div class=\"tips-card var-view var-3-view\">\n<h3>💡 Секреты идеального результата (Вариация 3)</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🔥 Секрет равномерного дна (155°C)</strong>\n<p>Толщина слоя уменьшена (сырой вес ~680 г вместо 820 г), а температура снижена до 155–160°C. Тепло успевает прогреть и схватить дно, пока верх подрумянивается.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🌱 10–12 г псиллиума без муки</strong>\n<p>Псиллиум связывает сыворотку мягкого творога, формируя стабильное пломбирное суфле без муки и крахмала.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🍦 Ванилин Dr. Bakers (1–2 г)</strong>\n<p>Большой объем творожной базы (370 г) и 45 г сывороточного протеина отлично балансируют этилванилин: 1–2 г создают глубокий пломбирный аромат без горечи.</p>\n</div>\n</div>\n</div><div class=\"tips-card var-view var-4-view\">\n<h3>💡 Секреты идеального результата (Вариация 4)</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🥚 3 белка без миксера и взбивания</strong>\n<p>Белки отправляются сразу в блендер вместе с творогом — миксер не нужен! Отказ от желтков снижает жирность до 4.2 г, сохраняя шелковистую плотную текстуру чизкейка.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🌱 2 ч. л. псиллиума — монолитное дно</strong>\n<p>Псиллиум равномерно впитывает свободную сыворотку, связывая белки и творог. Дно гарантированно пропекается, не оседает и не мокнет.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🔥 155°C и 7 стиков ФитПарада</strong>\n<p>Мягкая температура 155°C равномерно прогревает всю толщу чизкейка без трещин, а 7 стиков ФитПарада идеально балансируют 530 г творожной базы.</p>\n</div>\n</div>\n</div><div class=\"tips-card var-view var-5-view\">\n<h3>💡 Секреты идеального результата (Вариация 5)</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🍋 Лимонная кислота в воде — секрет баланса</strong>\n<p>Растворение 1/4 ч. л. кислоты в 1 ч. л. воды обеспечивает ее идеальное распределение по тесту без крупинок, освежая вкус сгущенки и подчеркивая сливочность.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🧀 Трио творогов — идеальная текстура</strong>\n<p>«Першино» дает сливочность, «Ирбитский» обеспечивает плотный каркас и белок, а «Савушкин» дает необходимую влагу для легкого взбивания блендером.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🔥 140 г белка и рекордные 19.2 г на 100 г</strong>\n<p>Всего 142 ккал и 3.9 г жиров на 100 г готового чизкейка делают этот десерт абсолютным лидером для сушки и сытного правильного питания.</p>\n</div>\n</div>\n</div><div class=\"tips-card var-view var-6-view\">\n<h3>💡 Секреты идеального результата (Вариация 6)</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🥚 3 яйца С0 — сочность сухого творога</strong>\n<p>Обезжиренный творог «Красная цена» сухой, а варенка густая. 3 яйца С0 дают необходимую влагу (+55 г) и полезные жиры, делая чизкейк сочным и шелковистым.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🍋 Лимонная кислота против приторности</strong>\n<p>Обязательно растворите 1/4 ч. л. кислоты в 1 ч. л. воды — это нивелирует сладость сахарозы в сгущенке и подчеркнет карамельно-сливочный букет.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🔥 160°C вместо 170°C</strong>\n<p>Карамельные сахара варенки колеруются быстрее обычного сахара. Температура 160°C позволяет пропечь всю толщу без подгорания корочки.</p>\n</div>\n</div>\n</div>"}, {"slug": "chocolate-cherry-cheesecake.html", "title": "Шоколадно-вишневый ПП-чизкейк «Черный лес»", "shortTitle": "Шоколадно-вишневый «Черный лес»", "description": "Насыщенный вкус темного шоколада, терпкий вишневый аромат на сиропе без калорий, тающая кремовая текстура и рекордное содержание протеина при минимуме углеводов.", "image": "chocolate-cherry.png", "time": "20 минут", "difficulty": "Простая", "tags": ["Без добавленного сахара", "Высокобелковое", "До 20 мин"], "category": "Десерты", "defaultVariant": 1, "variants": [{"id": 1, "name": "Оригинальный рецепт", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "20 минут"}, {"label": "Температура", "value": "170°C"}, {"label": "Порций", "value": "4 порции"}, {"label": "Готовый вес", "value": "~650 грамм"}], "total": {"label": "На весь чизкейк Вес ~650 г", "kcal": 836.0, "macros": [{"label": "Белки", "value": 124.5}, {"label": "Жиры", "value": 21.9}, {"label": "Углеводы", "value": 20.6}, {"label": "Клетчатка", "value": 13.0}]}, "per100": {"label": "На 100 г готового Ультра-лайт", "kcal": 128.0, "macros": [{"label": "Белки", "value": 19.1}, {"label": "Жиры", "value": 3.3}, {"label": "Углеводы", "value": 3.2}, {"label": "Клетчатка", "value": 2.0}]}, "ingredients": [{"name": "Творог в брикете (0.1–2%)", "amount": "400 г (2 пачки)"}, {"name": "Греческий йогурт или мягкий творог (0.1–2.5%)", "amount": "120 г (1 шт)"}, {"name": "Яйца куриные С0", "amount": "2 шт (~125 г)"}, {"name": "Протеин КСБ-80 (без вкуса)", "amount": "30 г (1 скуп)"}, {"name": "Какао-порошок (темный/алкализованный)", "amount": "20 г (~1.5 ст. л.)"}, {"name": "Сироп 0 ккал «Вишня-Шоколад»", "amount": "50–60 мл"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "4–5 стиков"}, {"name": "Псиллиум (шелуха)", "amount": "3 ч. л. с горкой (~15 г)"}, {"name": "Соль мелкая", "amount": "Щепотка"}], "steps": [{"title": "Жидкая шоколадная база", "html": "<div class=\"step-content\">\n<p>В чашу блендера выложите творог (400 г), греческий йогурт (120 г), 2 яйца С0, влейте 50–60 мл сиропа «Вишня-Шоколад» без сахара.</p>\n</div>"}, {"title": "Взбивание с какао и протеином", "html": "<div class=\"step-content\">\n<p>Добавьте 20 г какао-порошка, протеин (30 г), 4–5 стиков ФитПарада и щепотку соли. Пробейте блендером 2 минуты до шелковистого темно-шоколадного крема.</p>\n</div>"}, {"title": "Введение псиллиума", "html": "<div class=\"step-content\">\n<p>Всыпьте 3 ч. л. псиллиума, перемешайте лопаткой и <strong>оставьте на 5–7 минут</strong> для набухания и стабилизации массы.</p>\n</div>"}, {"title": "Выпекание в аэрогриле", "html": "<div class=\"step-content\">\n<p>Форму (диаметр 16–18 см) застелите пергаментом, выложите шоколадную массу. Выпекайте при <strong>170°C в течение 20 минут</strong>.</p>\n</div>"}, {"title": "Охлаждение и подача", "html": "<div class=\"step-content\">\n<p>Остудите до комнатной температуры и уберите в холодильник на 2–3 часа. При подаче полейте сверху 1 ложкой сиропа «Вишня-Шоколад»!</p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card\">\n<h3>💡 Секреты идеального «Черного леса»</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🍫 Алкализованное какао</strong>\n<p>Дает насыщенный темный цвет и мягкий шоколадный вкус без лишней горечи.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🍒 Двойная вишня</strong>\n<p>Сироп в тесте дает аромат, а пара ложек сиропа сверху при подаче делает десерт невероятно сочным.</p>\n</div>\n<div class=\"tip-box\">\n<strong>💪 Всего 128 ккал</strong>\n<p>Благодаря 0-калорийному сиропу калорийность на 100 г упала до рекордных 128 ккал при 19 г белка!</p>\n</div>\n</div>\n</div>"}, {"slug": "creamy-chicken-potatoes.html", "title": "Сливочная курочка с картофелем в аэрогриле", "shortTitle": "Сливочная курочка с картофелем", "description": "Золотистый запеченный картофель, нежнейшее куриное филе в шелковистом чесночном крем-соусе с пармезаном и тянущейся моцареллой. Идеальный сытный рацион для набора сухой массы и дефицита калорий.", "image": "creamy-chicken-potatoes.png", "time": "25 минут", "difficulty": "Простая", "tags": ["Без добавленного сахара", "Высокобелковое"], "category": "Основные блюда", "defaultVariant": 1, "variants": [{"id": 1, "name": "Оригинальный рецепт", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "25 минут"}, {"label": "Температура гриля", "value": "190–200°C"}, {"label": "Порций", "value": "4 порции"}, {"label": "Готовый вес", "value": "~1600 грамм"}], "total": {"label": "На всё блюдо Вес ~1.6 кг", "kcal": 2212.0, "macros": [{"label": "Белки", "value": 240.0}, {"label": "Жиры", "value": 71.5}, {"label": "Углеводы", "value": 145.0}]}, "per100": {"label": "На 100 г готового Эталон", "kcal": 138.0, "macros": [{"label": "Белки", "value": 15.0}, {"label": "Жиры", "value": 4.5}, {"label": "Углеводы", "value": 9.1}]}, "ingredients": [{"name": "Куриное филе (грудка)", "amount": "800 г"}, {"name": "Картофель (очищенный)", "amount": "800 г"}, {"name": "Творожный сыр Hochland", "amount": "140 г (1 баночка)"}, {"name": "Пармезан тёртый", "amount": "40–50 г"}, {"name": "Моцарелла для пиццы", "amount": "50–60 г"}, {"name": "Молоко 1.5–2.5%", "amount": "120–150 мл"}, {"name": "Сухой чеснок и паприка", "amount": "по 1 ч. л."}, {"name": "Соль, перец, травы", "amount": "по вкусу"}, {"name": "Свежая петрушка", "amount": "для подачи"}], "steps": [{"title": "Запекание картофеля в аэрогриле", "html": "<div class=\"step-content\">\n<p>Картофель нарежьте кубиками, смешайте с солью, паприкой и чесноком. Запекайте в аэрогриле при <strong>195–200°C 18–20 минут</strong> до золотистой корочки.</p>\n</div>"}, {"title": "Сочное филе на пергаменте", "html": "<div class=\"step-content\">\n<p>Куриное филе нарежьте кубиками, обваляйте в специях с 1 ч. л. масла. Застелите чашу аэрогриля пергаментом, выложите мясо и запекайте <strong>14–16 минут при 185–190°C</strong> в собственном соку.</p>\n</div>"}, {"title": "Варка сливочно-сырного соуса", "html": "<div class=\"step-content\">\n<p>В кастрюлю на плите влейте молоко (120–150 мл), выложите творожный сыр Hochland и 40–50 г пармезана. На слабом огне помешивайте 1.5–2 минуты до получения густого гладкого крема.</p>\n</div>"}, {"title": "Сборка и пропитка блюда", "html": "<div class=\"step-content\">\n<p>Переложите горячую курицу в кастрюлю <strong>вместе со всем соком с пергамента</strong>, всыпьте картофель и тщательно перемешайте лопаткой, чтобы соус обволок каждый кусочек.</p>\n</div>"}, {"title": "Сырная шапка и подача", "html": "<div class=\"step-content\">\n<p>Посыпьте поверхность моцареллой (50–60 г), накройте кастрюлю крышкой на <strong>4–5 минут</strong> на выключенной плите до расплавления сыра. При подаче украсьте свежей петрушкой!</p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card\">\n<h3>💡 Секреты сочности и экономии времени</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🍗 Пергамент решает всё</strong>\n<p>Мясной сок не утекает сквозь решетку, а сохраняется и обогащает сливочный соус в кастрюле.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🥔 121 ккал на 100 г</strong>\n<p>Огромный объем сытной еды с картофелем и сыром при калорийности легче, чем у диетической овсянки!</p>\n</div>\n<div class=\"tip-box\">\n<strong>🍱 Идеальный Meal-Prep</strong>\n<p>Раскладывается на 6 контейнеров. В разогретом виде блюдо остается таким же сочным и нежным.</p>\n</div>\n</div>\n</div>"}, {"slug": "banana-cheesecake-souffle.html", "title": "Банановый ПП-чизкейк суфле в аэрогриле", "shortTitle": "Банановый чизкейк-суфле", "description": "Нежнейшая кремовая текстура суфле, натуральная сладость банана и идеальная плотность благодаря кукурузному крахмалу. Без лишней влаги в тесте. Всего 122 ккал на 100 г!", "image": "banana-souffle.png", "time": "26–28 минут", "difficulty": "Простая", "tags": ["Высокобелковое"], "category": "Десерты", "defaultVariant": 1, "variants": [{"id": 1, "name": "Оригинальный рецепт", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "26–28 минут"}, {"label": "Температура", "value": "160–165°C"}, {"label": "Порций", "value": "4 порции"}, {"label": "Готовый вес", "value": "~750 грамм"}], "total": {"label": "На весь чизкейк Вес ~750 г", "kcal": 916.0, "macros": [{"label": "Белки", "value": 118.0}, {"label": "Жиры", "value": 19.6}, {"label": "Углеводы", "value": 65.4}]}, "per100": {"label": "На 100 г готового Супер-лайт", "kcal": 122.0, "macros": [{"label": "Белки", "value": 15.7}, {"label": "Жиры", "value": 2.6}, {"label": "Углеводы", "value": 8.7}]}, "ingredients": [{"name": "Творог обезжиренный («Красная цена» 0%)", "amount": "360 г (2 пачки)"}, {"name": "Греческий йогурт («Простоквашино» 2%)", "amount": "235 г (1 банка)"}, {"name": "Спелый банан", "amount": "1 шт (~110 г)"}, {"name": "Яйца куриные С0", "amount": "2 шт (~125 г)"}, {"name": "Сывороточный протеин (ваниль/пломбир)", "amount": "30 г (1 скуп)"}, {"name": "Кукурузный крахмал", "amount": "25–30 г (1.5–2 ст. л.)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "5–6 стиков"}, {"name": "Соль мелкая", "amount": "щепотка"}, {"name": "Сироп 0 ккал «Сгущенка» (для подачи)", "amount": "топпинг по вкусу"}], "steps": [{"title": "Закладка основы в блендер", "html": "<div class=\"step-content\">\n<p>В чашу блендера выложите творог (360 г), банку греческого йогурта (235 г), нарезанный спелый банан и разбейте 2 яйца С0. Жидкий сироп в само тесто не добавляем, чтобы не переувлажнять массу!</p>\n</div>"}, {"title": "Добавление сухих компонентов и взбивание", "html": "<div class=\"step-content\">\n<p>Всыпьте 30 г протеина, 25–30 г кукурузного крахмала, 5–6 стиков ФитПарада и щепотку соли (она балансирует вкус). Тщательно пробейте блендером 2–2.5 минуты до гладкой шелковистой текстуры без крупинок.</p>\n</div>"}, {"title": "Подготовка формы", "html": "<div class=\"step-content\">\n<p>Форму для запекания (диаметр 16–18 см) застелите пергаментом (дно и бортики). Аккуратно перелейте творожную массу и слегка постучите формой об стол, чтобы вышли крупные пузырьки.</p>\n</div>"}, {"title": "Выпекание в аэрогриле", "html": "<div class=\"step-content\">\n<p>Выпекайте при температуре <strong>160–165°C в течение 26–28 минут</strong>. Умеренная температура позволяет тесту пропечься в глубину без пересушивания и подгорания верхушки.</p>\n</div>"}, {"title": "Остывание и стабилизация в холоде", "html": "<div class=\"step-content\">\n<p>Дайте чизкейку полностью остыть в форме при комнатной температуре, затем <strong>уберите в холодильник минимум на 3–4 часа</strong>. Кукурузный крахмал полностью стабилизирует влагу, создав нежнейшую текстуру суфле!</p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card\">\n<h3>💡 Секреты идеального бананового суфле</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🍯 Топпинг при подаче</strong>\n<p>Полейте охлажденный кусочек 0-калорийным сиропом со сгущенкой прямо сверху перед едой — так сохранится плотность чизкейка и яркий карамельный акцент!</p>\n</div>\n<div class=\"tip-box\">\n<strong>🌽 Роль крахмала</strong>\n<p>В банане и йогурте много жидкости. 25–30 г кукурузного крахмала надежно связывают влагу в аэрогриле, предотвращая сырую сердцевину.</p>\n</div>\n<div class=\"tip-box\">\n<strong>⚡ 122 ккал и сытость</strong>\n<p>На 1 порцию (1/4 пирога) — 229 ккал и почти 30 г чистого белка. Прекрасный сытный десерт или полноценный прием пищи.</p>\n</div>\n</div>\n</div>"}, {"slug": "juicy-chicken-breast.html", "title": "Сочная куриная грудка в собственном соку (1 кг)", "shortTitle": "Сочная курочка в соку (1 кг)", "description": "Проверенный метод запекания сразу 1 кг филе в 2 слоя на сплошном пергаменте. Ровно 24 минуты при 200°C (4 захода по 6 минут с перемешиванием). Мясо не пересыхает, томится в соке и остается мягким!", "image": "juicy-chicken-breast.png", "time": "24 минуты", "difficulty": "Простая", "tags": ["Без добавленного сахара", "Высокобелковое", "Кето"], "category": "Основные блюда", "defaultVariant": 1, "variants": [{"id": 1, "name": "Оригинальный рецепт", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "24 минуты"}, {"label": "Температура", "value": "200°C"}, {"label": "Порций", "value": "4 порции"}, {"label": "Сырой / готовый вес", "value": "1000 г / ~750 г"}], "total": {"label": "На весь килограмм филе Вес ~750 г", "kcal": 1190.0, "macros": [{"label": "Белки", "value": 236.0}, {"label": "Жиры", "value": 13.0}, {"label": "Углеводы", "value": 0.8}]}, "per100": {"label": "На 100 г готового Супер-белок", "kcal": 158.0, "macros": [{"label": "Белки", "value": 31.5}, {"label": "Жиры", "value": 2.5}, {"label": "Углеводы", "value": 0.2}]}, "ingredients": [{"name": "Куриное филе (грудка)", "amount": "1 кг (1000 г)"}, {"name": "Растительное / оливковое масло", "amount": "1–1.5 ч. л. (7–10 г)"}, {"name": "Паприка сладкая или копченая", "amount": "1.5–2 ч. л."}, {"name": "Сушеный чеснок гранулированный", "amount": "1–1.5 ч. л."}, {"name": "Соль мелкая", "amount": "1 ч. л. без горки (~6 г)"}, {"name": "Черный свежемолотый перец", "amount": "0.5 ч. л."}, {"name": "Прованские травы / хмели-сунели", "amount": "1 ч. л. (по вкусу)"}], "steps": [{"title": "Нарезка 1 кг филе", "html": "<div class=\"step-content\">\n<p>Промойте 1 кг куриного филе, тщательно обсушите бумажными полотенцами и нарежьте кубиками размером 2.5–3 см.</p>\n</div>"}, {"title": "Маринование со специями", "html": "<div class=\"step-content\">\n<p>В большой миске смешайте все кусочки с 1–1.5 ч. л. масла, паприкой, сушеным чесноком, солью, перцем и травами. Хорошо перемешайте руками, чтобы специи распределились по всей массе мяса.</p>\n</div>"}, {"title": "Выкладка в 2 слоя на пергамент", "html": "<div class=\"step-content\">\n<p>На дно корзины аэрогриля выстелите <strong>сплошной пергамент</strong> (без перфорации!) с бортиками. Высыпьте все мясо — за счет объема (1 кг) оно ляжет <strong>в 2 слоя</strong>. Это ключевой фактор сочности: выделяющийся сок создаст эффект нежного томления!</p>\n</div>"}, {"title": "Запекание «4 по 6» (24 мин на 200°C)", "html": "<div class=\"step-content\">\n<p>Выпекайте при температуре <strong>200°C ровно 24 минуты</strong>. Каждые <strong>6 минут</strong> выдвигайте корзину и тщательно перемешивайте слои лопаткой, чтобы нижние и верхние кусочки менялись местами.</p>\n</div>"}, {"title": "Результат: сочность и запас на дни вперед", "html": "<div class=\"step-content\">\n<p>Первые 12 минут мясо томится в собственном ароматном бульоне, а во второй половине времени сок выпаривается и карамелизуется, глазируя кусочки. Мясо остается нежнейшим! Идеальный запас белка на 3–4 дня вперед.</p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card\">\n<h3>💡 Секреты сочного килограмма в аэрогриле</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🍱 Почему именно 1 кг в 2 слоя?</strong>\n<p>Небольшая порция филе на воздухе может быстро высохнуть. А килограмм в 2 слоя на пергаменте выделяет много сока, в котором мясо мягко томится и сохраняет сочность.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🔄 Роль 4 перемешиваний</strong>\n<p>Каждые 6 минут слои меняются местами: кусочки поочередно то томятся в соке на дне, то подрумяниваются сверху под обдувом горячего воздуха.</p>\n</div>\n<div class=\"tip-box\">\n<strong>⏱ А если готовить меньше (500 г)?</strong>\n<p>Если готовите полкило в 1 свободный слой, сократите время почти вдвое: достаточно 12–14 минут (2 захода по 6–7 минут).</p>\n</div>\n</div>\n</div>"}, {"slug": "creamy-buckwheat.html", "title": "Томленая сливочная гречка в аэрогриле", "shortTitle": "Томленая сливочная гречка", "description": "Нежнейшая, рассыпчатая и бархатистая гречневая каша на молоке 2.5% со сливочным маслом и эффектом томления в русской печи. Идеальный сочный гарнир к запеченной куриной грудке.", "image": "creamy-buckwheat-hero.jpg", "time": "26–28 минут", "difficulty": "Простая", "tags": ["Без добавленного сахара"], "category": "Завтраки", "defaultVariant": 1, "variants": [{"id": 1, "name": "Оригинальный рецепт", "baseServings": 3, "meta": [{"label": "Время готовки", "value": "26–28 минут"}, {"label": "Температура", "value": "165–170°C"}, {"label": "Порций", "value": "3 человека"}, {"label": "Готовый вес", "value": "~850 грамм"}], "total": {"label": "На всю кастрюлю Вес ~850 г", "kcal": 1123.0, "macros": [{"label": "Белки", "value": 40.7}, {"label": "Жиры", "value": 29.3}, {"label": "Углеводы", "value": 166.0}]}, "per100": {"label": "На 100 г готовой каши Главное ⭐", "kcal": 132.0, "macros": [{"label": "Белки", "value": 4.8}, {"label": "Жиры", "value": 3.5}, {"label": "Углеводы", "value": 19.5}]}, "ingredients": [{"name": "Гречневая крупа (ядрица)", "amount": "240 г (сухая)"}, {"name": "Крутой кипяток (1-й этап)", "amount": "350 мл"}, {"name": "Молоко 2.5% (горячее)", "amount": "350 мл"}, {"name": "Соль мелкая / морская", "amount": "1 ч. л. без горки (~5 г)"}, {"name": "Сливочное масло 82.5%", "amount": "15 г (по 5 г на чел)"}, {"name": "Свежемолотый черный перец", "amount": "1/4 ч. л."}, {"name": "Лавровый лист (по желанию)", "amount": "1 шт"}], "steps": [{"title": "Промывка и запаривание в кипятке (15–20 мин)", "html": "<div class=\"step-content\">\n<p>240 г гречки промойте 2–3 раза холодной водой и полностью слейте влагу. Пересыпьте крупу в жаропрочную форму (объемом от 1.5 л), добавьте 1 ч. л. соли, черный перец и лавровый лист. Залейте <strong>350 мл крутого кипятка</strong> и оставьте на столе на 15–20 минут. Зерна впитают воду, набухнут и начнут размягчаться.</p>\n<div class=\"step-img-box\">\n<img alt=\"Шаг 1: Запаривание гречки в кипятке\" src=\"buckwheat-step-steep.jpg\"/>\n</div>\n</div>"}, {"title": "Введение горячего молока 2.5%", "html": "<div class=\"step-content\">\n<p>Подогрейте <strong>350 мл молока 2.5%</strong> в микроволновке или ковшике почти до закипания (горячее молоко не остановит прогрев зерен). Влейте горячее молоко в форму прямо к набухшей гречке и аккуратно перемешайте лопаткой.</p>\n<div class=\"step-img-box\">\n<img alt=\"Шаг 2: Введение горячего молока\" src=\"buckwheat-step-milk.jpg\"/>\n</div>\n</div>"}, {"title": "Герметичная запечатка фольгой в 2 слоя", "html": "<div class=\"step-content\">\n<p>Плотно накройте форму <strong>двумя слоями фольги</strong>, тщательно обжав бортики вокруг емкости. Это критически важно: в аэрогриле мощный конвекционный обдув, без фольги верхние зерна высохнут, а под фольгой создается эффект томления в глиняном горшочке.</p>\n<div class=\"step-img-box\">\n<img alt=\"Шаг 3: Запечатка формы фольгой\" src=\"buckwheat-step-foil.jpg\"/>\n</div>\n</div>"}, {"title": "Томление в аэрогриле (165–170°C, 26–28 мин)", "html": "<div class=\"step-content\">\n<p>Установите форму в корзину аэрогриля. Выпекайте при температуре <strong>165–170°C в течение 26–28 минут</strong>. Умеренная температура предотвращает бурное закипание молока и позволяет крупе впитать всю молочную сливочность.</p>\n</div>"}, {"title": "Дозревание на остаточном тепле и сливочное масло", "html": "<div class=\"step-content\">\n<p>Достаньте форму из аэрогриля, <strong>не вскрывая фольгу</strong>, и оставьте на столе на 10–15 минут (в это время можно быстро запечь курочку!). Перед подачей снимите фольгу, удалите лавровый лист, положите 15 г сливочного масла и перемешайте. Каша получается бархатистой, рассыпчатой и нежной!</p>\n</div>"}]}], "extraHtml": "<div class=\"workflow-banner\">\n<div class=\"workflow-title\">\n<span>🍗</span> Тайминг идеального ужина с куриной грудкой\n            </div>\n<p class=\"workflow-desc\">\n                Чтобы подать горячую сочную куриную грудку и томленую сливочную гречку одновременно, используйте правило бесшовного конвейера аэрогриля:\n            </p>\n<div class=\"workflow-timeline\">\n<div class=\"timeline-box\">\n<div class=\"timeline-time\">Этап 1 (20 минут)</div>\n<div class=\"timeline-action\">Гречка запаривается кипятком на столе. Грудка уже в маринаде.</div>\n</div>\n<div class=\"timeline-box\">\n<div class=\"timeline-time\">Этап 2 (28 минут)</div>\n<div class=\"timeline-action\">Гречка с молоком томится в аэрогриле под фольгой (165–170°C).</div>\n</div>\n<div class=\"timeline-box\">\n<div class=\"timeline-time\">Этап 3 (16–18 минут)</div>\n<div class=\"timeline-action\">Гречка доходит под фольгой на столе. В аэрогриль загружается грудка (180°C)!</div>\n</div>\n</div>\n</div><div class=\"tips-card\">\n<h3>💡 Секреты идеального результата</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🥛 Почему именно 50/50 вода и молоко</strong>\n<p>В чистом молоке гречневое зерно разваривается медленнее из-за казеина. Кипяток быстро раскрывает крупу, а горячее молоко дает нежный сливочный вкус без пригорания.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🛡️ Фольга в 2 слоя — эффект русской печи</strong>\n<p>Плотная фольга блокирует испарение влаги и защищает от прямого верхнего обдува тэна. Крупинки пропариваются равномерно снизу доверху.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🧈 15 г масла в конце</strong>\n<p>Не добавляйте масло в начале: молочный жир при высокой температуре может оседать на дно. Растопленное в горячей каше масло в конце обволакивает каждую крупинку.</p>\n</div>\n</div>\n</div>"}, {"slug": "chocolate-kefir-shake.html", "title": "Шоколадный протеиновый био-шейк на кефире", "shortTitle": "Шоколадный протеиновый био-шейк", "description": "Густой, кремовый шоколадный шейк на 1% кефире с чистым сывороточным протеином и классическим какао «Золотой Ярлык». Без сахара, с легкой сливочной кислинкой и бархатистой пенкой. Готовится в шейкере за 2 минуты!", "image": "chocolate-kefir-shake.png", "time": "2 минуты", "difficulty": "Простая", "tags": ["Без добавленного сахара", "Высокобелковое", "До 20 мин"], "category": "Напитки", "defaultVariant": 1, "variants": [{"id": 1, "name": "Оригинальный рецепт", "baseServings": 1, "meta": [{"label": "Время готовки", "value": "2 минуты"}, {"label": "Способ приготовления", "value": "Фитнес-шейкер"}, {"label": "Количество порций", "value": "1 порция"}, {"label": "Вес готового коктейля", "value": "~287 г"}], "total": {"label": "На весь шейк (~287 г) Порция целиком", "kcal": 237.0, "macros": [{"label": "Белки", "value": 33.2}, {"label": "Жиры", "value": 5.0}, {"label": "Углеводы", "value": 12.7}]}, "per100": {"label": "На 100 г коктейля Высокий белок", "kcal": 82.6, "macros": [{"label": "Белки", "value": 11.6}, {"label": "Жиры", "value": 1.7}, {"label": "Углеводы", "value": 4.4}]}, "ingredients": [{"name": "Кефир 1% («Ирбитский» или легкий биокефир)", "amount": "250 г"}, {"name": "Сывороточный протеин КСБ (без добавок)", "amount": "30 г (1 мерный скуп)"}, {"name": "Какао-порошок («Золотой Ярлык»)", "amount": "7 г (десертная ложка)"}, {"name": "Подсластитель (ФитПарад №7/№10)", "amount": "2–3 стика (по вкусу)"}, {"name": "Ванилин (по желанию)", "amount": "щепотка"}], "steps": [{"title": "Жидкая основа — первой", "html": "<div class=\"step-content\">\n<p>Налейте на дно чистого сухого шейкера ровно <strong>250 г охлажденного 1% кефира</strong>. Заливать жидкость первой обязательно: если насыпать сухие порошки на сухое дно, они прилипнут к пластику и останутся неразмешанными.</p>\n</div>"}, {"title": "Закладка сухих ингредиентов", "html": "<div class=\"step-content\">\n<p>Поверх кефира засыпьте <strong>30 г сывороточного протеина</strong> без добавок, ровно <strong>7 г какао «Золотой Ярлык»</strong> и <strong>2–3 стика сахарозаменителя</strong>. По желанию добавьте щепотку ванилина для аромата домашней выпечки.</p>\n</div>"}, {"title": "Взбивание в шейкере (30–45 сек)", "html": "<div class=\"step-content\">\n<p>Обязательно установите в шейкер <strong>сетку-рассекатель</strong> или опустите металлический пружинный шарик. Плотно закрутите крышку и защелкните питьевой клапан. Энергично взбалтывайте <strong>30–45 секунд</strong>: сначала вертикальными амплитудными движениями, затем круговыми.</p>\n</div>"}, {"title": "Оседание пены и подача", "html": "<div class=\"step-content\">\n<p>Дайте шейкеру спокойно постоять <strong>1–2 минуты</strong>. При взбивании сывороточный протеин образует объемную воздушную пенку — за минуту она осядет в плотную бархатистую сливочно-шоколадную шапку. Пейте сразу из шейкера или перелейте в охлажденный бокал!</p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card\">\n<h3>💡 Секреты идеального протеинового био-шейка</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🍫 Почему именно «Золотой Ярлык»?</strong>\n<p>Натуральное какао с жирностью 15% дает глубокий благородный вкус темного шоколада, полностью маскируя специфический молочный привкус чистого сывороточного белка без химических ароматизаторов.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🦠 Польза синбиотика для ЖКТ</strong>\n<p>Живые лакто- и бифидобактерии кефира в сочетании с полифенолами какао питают здоровую микрофлору кишечника и обеспечивают быстрое и легкое усвоение всей дозы белка (33 г).</p>\n</div>\n<div class=\"tip-box\">\n<strong>🥛 Баланс белков: сыворотка + казеин</strong>\n<p>Сочетание «быстрого» сывороточного белка из протеина и «медленного» казеина из кефира дает как мгновенную аминокислотную подпитку мышц, так и длительное чувство насыщения.</p>\n</div>\n</div>\n</div>"}, {"slug": "egg-white-scramble.html", "title": "Кремовый белковый скрэмбл с йогуртом «Теос»", "shortTitle": "Кремовый белковый скрэмбл", "description": "Нежнейший ресторанный омлет-скрэмбл с греческим йогуртом «Теос» (70 г) и молоком. Без сухой «резиновой» текстуры — тающие сливочные волны с гранулированным чесноком, свежим огурцом и колечками халапеньо.", "image": "egg-white-scramble.png", "time": "3 минуты", "difficulty": "Простая", "tags": ["Без добавленного сахара", "До 20 мин", "Кето"], "category": "Завтраки", "defaultVariant": 1, "variants": [{"id": 1, "name": "Только белки (4 шт. • 145 г)", "baseServings": 1, "meta": [{"label": "Время готовки", "value": "3 минуты"}, {"label": "Основа яиц", "value": "4 белка (145 г)"}, {"label": "Калорийность", "value": "144 ккал"}, {"label": "Чистый белок", "value": "22.8 г"}], "total": {"label": "На всю порцию скрэмбла Сковорода целиком", "kcal": 144.0, "macros": [{"label": "Белки", "value": 22.8}, {"label": "Жиры", "value": 3.6}, {"label": "Углеводы", "value": 5.6}]}, "per100": {"label": "На 100 г готового Низкая калорийность", "kcal": 58.0, "macros": [{"label": "Белки", "value": 9.1}, {"label": "Жиры", "value": 1.4}, {"label": "Углеводы", "value": 2.2}]}, "ingredients": [{"name": "Яичные белки (С0 / С1)", "amount": "4 шт (145 г)"}, {"name": "Греческий йогурт «Теос» 2%", "amount": "70 г (1/2 банки)"}, {"name": "Молоко 1.5–2.5%", "amount": "35 г (2–3 ст. л.)"}, {"name": "Масло растительное (распылитель)", "amount": "1–2 пшика (~1 г)"}, {"name": "Соль мелкая", "amount": "1/3 ч. л. (по вкусу)"}, {"name": "Сушеный чеснок гранулированный", "amount": "1/3 ч. л."}, {"name": "Черный свежемолотый перец", "amount": "щепотка"}, {"name": "Свежий огурец (для хрустящей подачи)", "amount": "50–70 г"}, {"name": "Перец халапеньо (маринованный или свежий)", "amount": "10–15 г (по вкусу)"}, {"name": "Свежая зелень (укроп или лук-шнитт)", "amount": "3–5 г"}], "steps": [{"title": "Взбивание сливочной основы", "html": "<div class=\"step-content\">\n<p>В глубокой миске соедините <strong>4 яичных белка (145 г)</strong>, <strong>70 г йогурта «Теос»</strong>, <strong>35 г молока</strong>, соль, свежемолотый перец и сушеный чеснок. Взбейте вилкой или венчиком 30–40 секунд до гладкой кремовой массы без крупных комочков.</p>\n</div>"}, {"title": "Подготовка сковороды", "html": "<div class=\"step-content\">\n<p>Поставьте антипригарную сковороду на <strong>умеренно-средний огонь</strong> (важно не раскалять сковороду, чтобы белок не сгорел и не стал сухим). Сделайте 1–2 пшика масла из распылителя.</p>\n</div>"}, {"title": "Формирование шелковистых волн", "html": "<div class=\"step-content\">\n<p>Вылейте смесь на сковороду. Подождите 15–20 секунд, пока нижний слой чуть-чуть схватится. Затем силиконовой лопаткой плавно и непрерывно сдвигайте массу <strong>от краев к центру</strong>, собирая нежные сливочные складки.</p>\n</div>"}, {"title": "Подача со свежим огурцом и халапеньо", "html": "<div class=\"step-content\">\n<p>Готовьте скрэмбл суммарно не более <strong>1.5–2 минут</strong>. Снимайте на тарелку, когда он еще <strong>слегка влажный и глянцевый</strong>: блюдо само дойдет до идеала за 30 секунд. Рядом выложите кружочки свежего огурца, колечки пикантного халапеньо и посыпьте свежей зеленью!</p>\n</div>"}]}, {"id": 2, "name": "Целые яйца (3 шт. • 165 г)", "baseServings": 1, "meta": [{"label": "Время готовки", "value": "3 минуты"}, {"label": "Основа яиц", "value": "3 яйца с желтками"}, {"label": "Калорийность", "value": "310 ккал"}, {"label": "Чистый белок", "value": "27.7 г"}], "total": {"label": "На всю порцию скрэмбла Сковорода целиком", "kcal": 310.0, "macros": [{"label": "Белки", "value": 27.7}, {"label": "Жиры (лецитин, омега)", "value": 19.0}, {"label": "Углеводы", "value": 5.8}]}, "per100": {"label": "На 100 г готового Плотная сытность", "kcal": 117.0, "macros": [{"label": "Белки", "value": 10.5}, {"label": "Жиры", "value": 7.2}, {"label": "Углеводы", "value": 2.2}]}, "ingredients": [{"name": "Яйца куриные С0 (целиком с желтками)", "amount": "3 шт (~165 г)"}, {"name": "Греческий йогурт «Теос» 2%", "amount": "70 г (1/2 банки)"}, {"name": "Молоко 1.5–2.5%", "amount": "35 г (2–3 ст. л.)"}, {"name": "Масло растительное (распылитель)", "amount": "1–2 пшика (~1 г)"}, {"name": "Соль мелкая", "amount": "1/3 ч. л. (по вкусу)"}, {"name": "Сушеный чеснок гранулированный", "amount": "1/3 ч. л."}, {"name": "Черный свежемолотый перец", "amount": "щепотка"}, {"name": "Свежий огурец (для хрустящей подачи)", "amount": "50–70 г"}, {"name": "Перец халапеньо (маринованный или свежий)", "amount": "10–15 г (по вкусу)"}, {"name": "Свежая зелень (укроп или лук-шнитт)", "amount": "3–5 г"}], "steps": [{"title": "Взбивание целых яиц с «Теосом»", "html": "<div class=\"step-content\">\n<p>Разбейте <strong>3 целых яйца</strong> в миску, добавьте <strong>70 г йогурта «Теос»</strong>, <strong>35 г молока</strong>, соль, перец и сушеный чеснок. Взбейте вилкой. Природный лецитин из желтков моментально соединяется с молочным белком йогурта в шелковистую золотистую эмульсию.</p>\n</div>"}, {"title": "Разогрев сковороды", "html": "<div class=\"step-content\">\n<p>Сбрызните антипригарную сковороду 1–2 пшиками масла из распылителя. Прогрейте на среднем огне (желтки более пластичны к нагреву, но не терпят перегрева).</p>\n</div>"}, {"title": "Сборка золотистых сливочных складок", "html": "<div class=\"step-content\">\n<p>Вылейте массу на сковороду. Подождите 15–20 секунд. Широкой силиконовой лопаткой сдвигайте нежные золотые волны от бортиков к центру. Текстура получается плотной, тающей и маслянистой без добавления сливочного масла.</p>\n</div>"}, {"title": "Подача с хрустящим огурцом и халапеньо", "html": "<div class=\"step-content\">\n<p>Снимите скрэмбл на тарелку слегка недожаренным и блестящим через 1.5–2 минуты. Дополните хрустящим свежим огурцом и колечками острого халапеньо — это невероятный ресторанный дуэт вкусов!</p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card var-view var-1-view\">\n<h3>💡 Секреты белкового скрэмбла на сушке (Вариация 1)</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🥛 Почему именно йогурт «Теос»?</strong>\n<p>Чистый яичный альбумин при нагреве быстро сжимается и выталкивает влагу (эффект «резины»). Плотный греческий йогурт удерживает влагу и дает нежнейшую текстуру ресторанного омлета на сливках при минимальной калорийности.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🔥 Умеренный огонь — закон нежности</strong>\n<p>Никогда не жарьте белки на сильном огне. Высокая температура мгновенно делает белок грубым. На среднем огне масса готовится бережно и сохраняет кремовую шелковистость.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🌶 Контраст огурца и халапеньо</strong>\n<p>Свежий сочный огурец дает идеальный хруст, а легкая остринка перца халапеньо великолепно оттеняет мягкую сливочную текстуру омлета.</p>\n</div>\n</div>\n</div><div class=\"tips-card var-view var-2-view\">\n<h3>💡 Секреты сытного скрэмбла с желтками (Вариация 2)</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🍳 Польза 3 цельных желтков</strong>\n<p>Желток содержит важнейший нутриент — холин (витамин B4 для печени и мозга), лютеин для зрения, биодоступное железо и витамины A, D, E. 3 яйца обеспечивают отличную суточную норму полезных жиров.</p>\n</div>\n<div class=\"tip-box\">\n<strong>✨ Природная шелковистость</strong>\n<p>Лецитин желтков работает как натуральный эмульгатор. В сочетании с греческим йогуртом скрэмбл обретает густую сливочную консистенцию ресторанного уровня.</p>\n</div>\n<div class=\"tip-box\">\n<strong>⚖️ Компромиссный баланс «2 + 2»</strong>\n<p>Если хочется снизить жиры, но сохранить солнечный цвет: используйте <strong>2 целых яйца + 2 белка</strong>. Это даст <strong>266 ккал, 28.7 г белка и всего 13.9 г жиров</strong>!</p>\n</div>\n</div>\n</div>"}, {"slug": "chocolate-banana-brownie.html", "title": "Шоколадно-банановый брауни-чизкейк", "shortTitle": "Шоколадно-банановый брауни", "description": "Влажный, тающий десерт с глубоким шоколадным вкусом какао «Золотой Ярлык», сладостью спелых бананов и нежной творожной основой. Овсяная мука с двойной порцией протеина надежно удерживают влагу без грамма пшеничной муки.", "image": "chocolate-banana-brownie.png", "time": "28 минут", "difficulty": "Простая", "tags": ["Без добавленного сахара", "Высокобелковое"], "category": "Десерты", "defaultVariant": 1, "variants": [{"id": 1, "name": "Оригинальный рецепт", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "28 минут"}, {"label": "Температура", "value": "160–165°C"}, {"label": "Количество порций", "value": "4–6 порций"}, {"label": "Вес готового", "value": "~715 г"}], "total": {"label": "На весь брауни (~715 г) Рекорд белка", "kcal": 1140.0, "macros": [{"label": "Белки", "value": 119.2}, {"label": "Жиры", "value": 36.2}, {"label": "Углеводы", "value": 83.0}]}, "per100": {"label": "На 100 г десерта Оптимальный баланс", "kcal": 159.0, "macros": [{"label": "Белки", "value": 16.7}, {"label": "Жиры", "value": 5.1}, {"label": "Углеводы", "value": 11.6}]}, "ingredients": [{"name": "Творог 5% («Моя цена»)", "amount": "360 г (2 пачки)"}, {"name": "Бананы спелые (очищенные)", "amount": "235 г (2 шт.)"}, {"name": "Яйца куриные С0", "amount": "2 шт (~120 г)"}, {"name": "Сывороточный протеин (базовый + шоколадный)", "amount": "45 г (1 скуп + 1 ст. л.)"}, {"name": "Какао-порошок («Золотой Ярлык»)", "amount": "15 г"}, {"name": "Овсяная мука", "amount": "25–30 г (1.5–2 ст. л.)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "7 стиков"}, {"name": "Разрыхлитель теста", "amount": "1/2 ч. л. (~3 г)"}, {"name": "Соль мелкая", "amount": "щепотка"}], "steps": [{"title": "Бананово-яичная основа", "html": "<div class=\"step-content\">\n<p>В чашу блендера поместите <strong>2 очищенных банана (235 г)</strong> и разбейте <strong>2 яйца С0</strong>. Измельчите погружным блендером 20–30 секунд до однородного жидкого фруктового пюре.</p>\n</div>"}, {"title": "Добавление творога и сухих компонентов", "html": "<div class=\"step-content\">\n<p>Добавьте <strong>360 г творога 5%</strong>, <strong>45 г протеина</strong> (базовый КСБ + ложка шоколадного), <strong>15 г какао «Золотой Ярлык»</strong>, <strong>25–30 г овсяной муки</strong>, <strong>7 стиков ФитПарада</strong>, 1/2 ч. л. разрыхлителя и обязательную <strong>щепотку соли</strong>.</p>\n</div>"}, {"title": "Взбивание до шелковистости", "html": "<div class=\"step-content\">\n<p>Тщательно пробейте массу погружным блендером 1.5–2 минуты. Все творожные крупинки должны раствориться. Тесто станет густым, глянцевым и насыщенно-шоколадным.</p>\n</div>"}, {"title": "Выпекание в аэрогриле (160–165°C, 26–28 мин)", "html": "<div class=\"step-content\">\n<p>Перелейте массу в силиконовую форму (d=16–18 см) или форму с пергаментом. Выпекайте при температуре <strong>160–165°C ровно 26–28 минут</strong>. Верх схватится ровной корочкой, а серединка останется нежной и слегка подвижной.</p>\n</div>"}, {"title": "Охлаждение и стабилизация", "html": "<div class=\"step-content\">\n<p>Дайте десерту полностью остыть при комнатной температуре, затем уберите в холодильник на 2–3 часа (идеально на ночь). Овсяная клетчатка свяжет остаточную влагу, и пирог приобретет эталонную плотную текстуру настоящего шоколадного брауни.</p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card\">\n<h3>💡 Секреты идеального бананового брауни</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🌾 Почему именно овсяная мука?</strong>\n<p>235 г бананов дают много фруктового сока. Овсяная мука с высоким содержанием бета-глюканов работает как естественный губка-стабилизатор, не давая тесту поплыть.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🧂 Секретная щепотка соли</strong>\n<p>Соль в шоколадной выпечке усиливает выработку вкусовых рецепторов, полностью убирает возможную горечь какао и раскрывает насыщенную карамельную сладость бананов.</p>\n</div>\n<div class=\"tip-box\">\n<strong>❄️ Подача только из холода</strong>\n<p>Теплый брауни покажется излишне мягким. После 3 часов в холодильнике он стабилизируется и нарезается идеальными ровными треугольниками с шелковистым срезом.</p>\n</div>\n</div>\n</div>"}, {"slug": "chocolate-fudge-cheesecake.html", "title": "Шоколадно-сливочный чизкейк со сгущенкой", "shortTitle": "Шоколадный чизкейк со сгущенкой", "description": "Нежнейший шоколадно-карамельный десерт с бархатной трюфельной текстурой на 1% сгущенке и твороге 5%. Псиллиум удерживает влагу и дает стабильную шелковистую основу без грамма муки и крахмала.", "image": "chocolate-fudge-cheesecake.png", "time": "26–28 минут", "difficulty": "Простая", "tags": ["Высокобелковое"], "category": "Десерты", "defaultVariant": 1, "variants": [{"id": 1, "name": "Оригинальный рецепт", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "26–28 минут"}, {"label": "Температура", "value": "160°C"}, {"label": "Количество порций", "value": "4–6 порций"}, {"label": "Вес готового", "value": "~660 г"}], "total": {"label": "На весь чизкейк (~660 г) Рекорд белка", "kcal": 1306.0, "macros": [{"label": "Белки", "value": 126.5}, {"label": "Жиры", "value": 36.4}, {"label": "Углеводы", "value": 112.1}]}, "per100": {"label": "На 100 г десерта Оптимальный баланс", "kcal": 198.0, "macros": [{"label": "Белки", "value": 19.2}, {"label": "Жиры", "value": 5.5}, {"label": "Углеводы", "value": 17.0}]}, "ingredients": [{"name": "Творог 5% («Моя цена»)", "amount": "360 г (2 пачки)"}, {"name": "Сгущенное молоко 1%", "amount": "170 г"}, {"name": "Яйца куриные С0", "amount": "2 шт (~120 г)"}, {"name": "Сывороточный протеин (КСБ 80)", "amount": "45 г (1.5 скупа)"}, {"name": "Какао-порошок («Золотой Ярлык»)", "amount": "20 г (2 ст. л.)"}, {"name": "Псиллиум (шелуха подорожника)", "amount": "5 г (1 ч. л.)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "4 стика"}, {"name": "Разрыхлитель теста", "amount": "1/2 ч. л. (~3 г)"}, {"name": "Соль мелкая", "amount": "щепотка"}], "steps": [{"title": "Творожно-сгущеночная основа", "html": "<div class=\"step-content\">\n<p>В чашу блендера выложите <strong>360 г творога 5%</strong>, разбейте <strong>2 яйца С0</strong> и влейте <strong>170 г 1% сгущенки</strong>. Пробейте погружным блендером 1–1.5 минуты до гладкого кремового состояния без комочков.</p>\n</div>"}, {"title": "Ввод шоколада, протеина и псиллиума", "html": "<div class=\"step-content\">\n<p>Добавьте <strong>45 г протеина</strong>, <strong>20 г какао «Золотой Ярлык»</strong>, <strong>1 ч. л. псиллиума (5 г)</strong>, <strong>4 стика ФитПарада</strong>, 1/2 ч. л. разрыхлителя и обязательную <strong>щепотку соли</strong>. Взбейте блендером до шелковистого шоколадного теста.</p>\n</div>"}, {"title": "Активация псиллиума (2 минуты)", "html": "<div class=\"step-content\">\n<p>Оставьте тесто постоять при комнатной температуре ровно 2 минуты. Псиллиум свяжет влагу, и тесто станет заметно более густым, шелковистым и послушным.</p>\n</div>"}, {"title": "Выпекание в аэрогриле (160°C, 25–28 мин)", "html": "<div class=\"step-content\">\n<p>Перелейте тесто в круглую форму диаметром 16–18 см (силиконовую или с пергаментом). Выпекайте в разогретом аэрогриле при <strong>160°C ровно 25–28 минут</strong>. Верх схватится матовой шоколадной корочкой, а серединка останется нежной и слегка подвижной.</p>\n</div>"}, {"title": "Охлаждение и стабилизация", "html": "<div class=\"step-content\">\n<p>Выключите аэрогриль и оставьте чизкейк с приоткрытой чашей на 15 минут. Затем полностью остудите при комнатной температуре и уберите в холодильник на 2–3 часа (идеально на ночь). Десерт застынет в плотный, тающий шоколадный трюфель.</p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card\">\n<h3>💡 Секреты шоколадного фаджа без муки</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🌱 Суперсила псиллиума</strong>\n<p>Шелуха подорожника формирует нежную гелевую матрицу. Десерт держит плотную форму чизкейка без муки и крахмала, насыщая блюдо полезной растворимой клетчаткой.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🥛 Сгущенка 1% для сливочного тела</strong>\n<p>Обезжиренная сгущенка дает десерту благородные карамельно-сливочные ноты «Ириски» и молочного шоколада, которые невозможно получить простым сахарозаменителем.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🧂 Секретная щепотка соли</strong>\n<p>Соль в шоколадной выпечке усиливает вкусовые рецепторы, нивелирует терпкость какао и делает вкус темного шоколада глубоким и ресторанным.</p>\n</div>\n</div>\n</div>"}, {"slug": "oat-bran-bread.html", "title": "Творожно-овсяный ПП-хлеб в аэрогриле", "shortTitle": "Творожно-овсяный ПП-хлеб", "description": "Ароматный цельнозерновой хлеб с хрустящей корочкой на овсяных отрубях и мягком твороге 0.1%. Доступно 2 выверенные вариации: классический плотный ржаной стиль и пышный пористый мякиш на псиллиуме.", "image": "oat-bran-bread.png", "time": "30–35 минут", "difficulty": "Простая", "tags": ["Без добавленного сахара", "Высокобелковое"], "category": "Выпечка", "defaultVariant": 2, "variants": [{"id": 2, "name": "Вариация 2: Пышный пористый", "baseServings": 9, "meta": [{"label": "Время выпечки", "value": "30–35 минут"}, {"label": "Температура", "value": "165°C"}, {"label": "Порций", "value": "9 ломтиков"}, {"label": "Готовый вес", "value": "~440 грамм"}], "total": {"label": "На всю буханку Вес ~440 г", "kcal": 746.0, "macros": [{"label": "Белки", "value": 59.0}, {"label": "Жиры", "value": 21.2}, {"label": "Углеводы", "value": 80.6}]}, "per100": {"label": "На 100 г готового Пышный & Белковый", "kcal": 170.0, "macros": [{"label": "Белки", "value": 13.4}, {"label": "Жиры", "value": 4.8}, {"label": "Углеводы", "value": 18.3}]}, "ingredients": [{"name": "Мягкий творог «Савушкин» 0.1%", "amount": "250 г (2 пачки по 125 г)"}, {"name": "Яйца куриные С0", "amount": "2 шт (~120 г) — подъем и объем"}, {"name": "Овсяные отруби", "amount": "100 г"}, {"name": "Кукурузный крахмал", "amount": "30 г (1.5 ст. л.)"}, {"name": "Псиллиум (шелуха подорожника)", "amount": "5 г (1 ч. л. с горкой) — поры мякиша"}, {"name": "Разрыхлитель теста", "amount": "1 ч. л. с горкой (5–6 г)"}, {"name": "Яблочный уксус (или лимонный сок)", "amount": "1 ч. л. (5 мл) — активатор газа"}, {"name": "Соль мелкая", "amount": "1 ч. л. без горки (5 г)"}, {"name": "Специи: кориандр / тмин / чеснок", "amount": "по 1/3 ч. л. (по вкусу)"}, {"name": "Семена кунжута или льна (для верха)", "amount": "1/2 ч. л. (для посыпки)"}], "steps": [{"title": "Взбивание жидкой базы", "html": "<div class=\"step-content\">\n<p>В глубокой миске взбейте вилкой или венчиком <strong>2 яйца С0</strong> с 1 ч. л. соли до появления легкой пенки. Добавьте <strong>250 г творога «Савушкин» 0.1%</strong> и <strong>1 ч. л. яблочного уксуса</strong>. Тщательно перемешайте до гладкой кремовой массы.</p>\n</div>"}, {"title": "Введение отрубей, псиллиума и крахмала", "html": "<div class=\"step-content\">\n<p>Всыпьте <strong>100 г овсяных отрубей</strong>, <strong>30 г кукурузного крахмала</strong>, <strong>5 г псиллиума</strong>, <strong>1 ч. л. с горкой разрыхлителя</strong> и хлебные специи (кориандр или тмин). Замесите лопаткой мягкое тесто.</p>\n</div>"}, {"title": "Отдых и активация газов (5–7 минут)", "html": "<div class=\"step-content\">\n<p>Оставьте тесто при комнатной температуре на 5–7 минут. Псиллиум свяжет свободную сыворотку, а уксус активирует разрыхлитель — в тесте образуется губчатая микропористая структура.</p>\n</div>"}, {"title": "Формовка и выпечка (165°C, 30–35 мин)", "html": "<div class=\"step-content\">\n<p>Выложите тесто в форму или сформируйте батончик на пергаменте, присыпьте семенами кунжута. За счет воздушных пор хлеб пропекается быстрее: выпекайте при <strong>165°C в течение 30–35 минут</strong>. Шпажка из центра должна выходить сухой.</p>\n</div>"}, {"title": "Остывание на решетке", "html": "<div class=\"step-content\">\n<p>Переложите буханку на решетку и <strong>дайте полностью остыть 25–30 минут</strong> перед нарезкой. Мякиш стабилизируется и станет пружинящим, мягким и не прессованным!</p>\n</div>"}]}, {"id": 1, "name": "Вариация 1: Классический плотный", "baseServings": 8, "meta": [{"label": "Время выпечки", "value": "40–44 минуты"}, {"label": "Температура", "value": "165°C"}, {"label": "Порций", "value": "8 ломтиков"}, {"label": "Готовый вес", "value": "~380 грамм"}], "total": {"label": "На всю буханку Вес ~380 г", "kcal": 642.0, "macros": [{"label": "Белки", "value": 51.3}, {"label": "Жиры", "value": 14.2}, {"label": "Углеводы", "value": 79.7}]}, "per100": {"label": "На 100 г готового Клетчатка & Белок", "kcal": 169.0, "macros": [{"label": "Белки", "value": 13.5}, {"label": "Жиры", "value": 3.7}, {"label": "Углеводы", "value": 21.0}]}, "ingredients": [{"name": "Мягкий творог «Савушкин» 0.1%", "amount": "250 г (2 пачки по 125 г)"}, {"name": "Овсяные отруби", "amount": "100 г"}, {"name": "Яйцо куриное С0", "amount": "1 шт (~60 г)"}, {"name": "Кукурузный крахмал", "amount": "30 г (1.5 ст. л.)"}, {"name": "Соль мелкая", "amount": "1 ч. л. без горки (~5 г)"}, {"name": "Разрыхлитель теста", "amount": "1/2 ч. л. (~3 г)"}], "steps": [{"title": "Смешивание влажной основы", "html": "<div class=\"step-content\">\n<p>В глубокую миску выложите <strong>250 г мягкого творога «Савушкин» 0.1%</strong>, разбейте <strong>1 яйцо С0</strong> и всыпьте <strong>1 ч. л. соли</strong>. Тщательно перемешайте венчиком до гладкой кремовой текстуры.</p>\n</div>"}, {"title": "Введение сухих компонентов", "html": "<div class=\"step-content\">\n<p>Добавьте <strong>100 г овсяных отрубей</strong>, <strong>30 г кукурузного крахмала</strong> и 1/2 ч. л. разрыхлителя. Тщательно вымешайте тесто лопаткой до равномерного распределения.</p>\n</div>"}, {"title": "Отдых теста (5–7 минут)", "html": "<div class=\"step-content\">\n<p>Оставьте тесто постоять при комнатной температуре. Овсяные отруби впитают влагу творога, а крахмал начнет набухать — масса станет плотной и вязкой.</p>\n</div>"}, {"title": "Выпекание в аэрогриле (165°C, 40–44 мин)", "html": "<div class=\"step-content\">\n<p>Переложите тесто в силиконовую или застеленную пергаментом форму, разровняйте лопаткой. Выпекайте при <strong>165°C в течение 40–44 минут</strong> (проверьте шпажкой по центру — она должна выходить сухой).</p>\n</div>"}, {"title": "Остывание на решетке", "html": "<div class=\"step-content\">\n<p>Извлеките буханку из формы и <strong>дайте полностью остыть на решетке 20–30 минут перед нарезкой</strong>. Плотная структура окончательно схватится.</p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card var-view var-2-view\">\n<h3>💡 Секреты идеального результата (Вариация 2)</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🍎 Тандем уксуса и разрыхлителя</strong>\n<p>Яблочный уксус создает активную кислую среду, стимулируя выделение $CO_2$. Запах уксуса полностью исчезает при выпечке, оставляя пористый мякиш.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🌱 Псиллиум как растительный каркас</strong>\n<p>Псиллиум удерживает пузырьки газа и влагу, заменяя клейковину белой муки. Хлеб пружинит при нажатии и не спрессовывается.</p>\n</div>\n<div class=\"tip-box\">\n<strong>💪 Рекордные 59 г чистого белка</strong>\n<p>Благодаря двум яйцам и творогу буханка дает 59 г белка при 18 г сложных углеводов. Идеально для завтраков и спортивного рациона.</p>\n</div>\n</div>\n</div><div class=\"tips-card var-view var-1-view\">\n<h3>💡 Секреты идеального результата (Вариация 1)</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🌾 Высокая сытость</strong>\n<p>Плотный мякиш долго переваривается, давая насыщение на 4–5 часов за счет максимальной концентрации овсяной клетчатки.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🌽 Кукурузный крахмал</strong>\n<p>Связывает влагу мягкого творога, предотвращая крошение плотного ломтика.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🥪 Поджарка в тостере</strong>\n<p>Ломтики этого хлеба идеально подрумяниваются в тостере или на сухой сковороде, приобретая хрустящую корочку.</p>\n</div>\n</div>\n</div>"}, {"slug": "sochniki.html", "title": "Творожные ПП-сочники с нежной начинкой", "shortTitle": "Творожные ПП-сочники", "description": "Пластичное творожное тесто на цельнозерновой муке с тающей ванильной начинкой. Легко раскатывается скалкой, не крошится в песок и складывается полумесяцем без трещин. 15 г чистого белка на один сочник!", "image": "sochniki.png", "time": "14–22 минут", "difficulty": "Средняя", "tags": ["Без добавленного сахара", "Высокобелковое"], "category": "Выпечка", "defaultVariant": 1, "variants": [{"id": 1, "name": "Оригинальный рецепт", "baseServings": 8, "meta": [{"label": "Время готовки", "value": "14–22 минут"}, {"label": "Температура", "value": "165°C / 180°C"}, {"label": "Количество", "value": "8–10 штук"}, {"label": "Вес готового", "value": "~740 г"}], "total": {"label": "Все сочники (~740 г) 3 пачки творога", "kcal": 1390.0, "macros": [{"label": "Белки", "value": 119.3}, {"label": "Жиры", "value": 42.5}, {"label": "Углеводы", "value": 129.4}]}, "per100": {"label": "На 100 г готового Плотность нутриентов", "kcal": 188.0, "macros": [{"label": "Белки", "value": 16.1}, {"label": "Жиры", "value": 5.7}, {"label": "Углеводы", "value": 17.5}]}, "ingredients": [{"name": "Творог 5% в брикетах", "amount": "360 г (2 пачки)"}, {"name": "Яйцо куриное С0 (целиком)", "amount": "1 шт."}, {"name": "Мука цельнозерновая пшеничная", "amount": "150–160 г"}, {"name": "Разрыхлитель теста", "amount": "1 ч. л. (5 г)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "4–5 саше (по вкусу)"}, {"name": "Соль мелкая", "amount": "щепотка"}, {"name": "Молоко 2.5% (если творог сухой)", "amount": "1–2 ст. л."}, {"name": "Творог 5% в брикетах", "amount": "180 г (1 пачка)"}, {"name": "Яичный белок С0 (от 2-го яйца)", "amount": "1 шт."}, {"name": "Кукурузный крахмал", "amount": "1 ст. л. (15 г)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "4–5 саше"}, {"name": "Ванилин", "amount": "1 г"}, {"name": "Яичный желток С0 (от 2-го яйца)", "amount": "1 шт."}, {"name": "Молоко 2.5%", "amount": "1 ст. л. (~15 мл)"}], "steps": [{"title": "Замес эластичного теста (без крошек)", "html": "<div class=\"step-content\">\n<p>В миске соедините <strong>360 г творога 5%</strong> (2 пачки), <strong>1 целое яйцо С0</strong>, щепотку соли и <strong>4–5 саше сахзама</strong>. Разомните вилкой в однородную кашицу (яйцо сразу свяжет сухой творог). Всыпьте <strong>150–160 г цельнозерновой муки</strong> с 1 ч. л. разрыхлителя. Замесите тесто руками: за 1–2 минуты оно соберется в податливый, эластичный шар, напоминающий мягкий пластилин. Если творог очень сухой — добавьте 1–2 ст. л. молока. Заверните шар в пленку и уберите в холод на <strong>15 минут</strong>.</p>\n</div>"}, {"title": "Приготовление творожной начинки", "html": "<div class=\"step-content\">\n<p>Для начинки соедините <strong>180 г творога</strong> (1 пачка), <strong>белок второго яйца</strong>, <strong>1 ст. л. кукурузного крахмала (15 г)</strong>, <strong>4–5 саше сахзама</strong> и 1 г ванилина (желток оставьте в пиале для смазки). Перетрите вилкой или взбейте блендером 20 секунд до сладкого густого крема.</p>\n</div>"}, {"title": "Раскатка и формовка (без трещин)", "html": "<div class=\"step-content\">\n<p>Припылите стол или коврик щепоткой муки. Раскатайте охлажденное тесто скалкой до толщины <strong>4–5 мм</strong> — благодаря клейковине цельнозерновой муки оно катается ровно, не липнет и не крошится в песок. Кружкой или формой вырежьте круги диаметром <strong>9–10 см</strong>. На одну половину круга выложите <strong>1 ст. л. с горкой начинки</strong>, накройте второй половиной полумесяцем. Тесто согнется легко и без трещин! <em>Края не защипывайте</em> — начинка должна аппетитно выглядывать сбоку.</p>\n</div>"}, {"title": "Румяная смазка и выпекание", "html": "<div class=\"step-content\">\n<p>В пиале взболтайте <strong>желток второго яйца с 1 ст. л. молока</strong> и кисточкой смажьте верхушки сочников (это обеспечит аппетитный пекарский глянец). Выберите режим:</p>\n<div class=\"baking-modes\">\n<div class=\"bake-box highlight\">\n<div class=\"bake-title\">💨 В аэрогриле (основной)</div>\n<div class=\"bake-desc\">\n                                        Дно корзины застелите пергаментом. Выпекайте партиями по 4–5 шт. при <strong>165–170°C ровно 14–16 минут</strong> до красивого золотистого цвета.\n                                    </div>\n</div>\n<div class=\"bake-box\">\n<div class=\"bake-title\">♨️ В духовке (на весь противень)</div>\n<div class=\"bake-desc\">\n                                        Разогрейте духовку до <strong>180°C</strong> (режим «Верх+Низ»). Выложите все сочники на противень с пергаментом и выпекайте <strong>20–25 минут</strong>.\n                                    </div>\n</div>\n</div>\n</div>"}, {"title": "Остывание и подача", "html": "<div class=\"step-content\">\n<p>Переложите сочники на решетку и дайте им постоять <strong>10–15 минут</strong>. Горячая творожная начинка стабилизируется, а тесто станет нежным и мягким.</p>\n</div>"}]}], "extraHtml": "<div class=\"baking-modes\">\n<div class=\"bake-box highlight\">\n<div class=\"bake-title\">💨 В аэрогриле (основной)</div>\n<div class=\"bake-desc\">\n                                        Дно корзины застелите пергаментом. Выпекайте партиями по 4–5 шт. при <strong>165–170°C ровно 14–16 минут</strong> до красивого золотистого цвета.\n                                    </div>\n</div>\n<div class=\"bake-box\">\n<div class=\"bake-title\">♨️ В духовке (на весь противень)</div>\n<div class=\"bake-desc\">\n                                        Разогрейте духовку до <strong>180°C</strong> (режим «Верх+Низ»). Выложите все сочники на противень с пергаментом и выпекайте <strong>20–25 минут</strong>.\n                                    </div>\n</div>\n</div><div class=\"tips-card\">\n<h3>💡 Секреты идеальных ПП-сочников</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🌾 Цельнозерновая мука вместо рисовой</strong>\n<p>Рисовая мука дает сухой рисовый привкус и распадается в песок. Цельнозерновая пшеничная мука содержит природный глютен: тесто катается скалкой и сгибается без трещин.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🍯 Творог требует больше сладости</strong>\n<p>Творог сильно приглушает сахарозаменитель: на 3 пачки творога (540 г) нужно не менее 8–10 саше ФитПарада суммарно (по 4–5 в тесто и в начинку), чтобы сочники были сладкими десертными.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🥚 2 яйца — безотходная связка</strong>\n<p>Первое яйцо идет целиком в тесто (влага белка склеивает творог). От второго яйца белок идет в начинку для густоты, а желток с молоком — на смазывание верха для глянцевой румяной корочки.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🥟 Фирменная открытая форма</strong>\n<p>Не прижимайте края сочника вилкой или пальцами. Классический советский сочник славится приоткрытой творожной серединкой с аппетитной каймой.</p>\n</div>\n</div>\n</div>"}, {"slug": "chocolate-banana-shake.html", "title": "Шоколадно-банановый протеиновый милкшейк", "shortTitle": "Шоколадно-банановый милкшейк", "description": "Густой сливочно-шоколадный коктейль с бархатной текстурой растаявшего мороженого. Молоко 2.5%, спелый банан, какао и чистый сывороточный протеин. Взбивается погружным блендером прямо в шейкере без лишней посуды!", "image": "chocolate-banana-shake.png", "time": "1–2 минуты", "difficulty": "Простая", "tags": ["Без добавленного сахара", "До 20 мин"], "category": "Напитки", "defaultVariant": 1, "variants": [{"id": 1, "name": "Оригинальный рецепт", "baseServings": 1, "meta": [{"label": "Время готовки", "value": "1–2 минуты"}, {"label": "Посуда", "value": "Шейкер + блендер"}, {"label": "Объем", "value": "1 бокал (~400 мл)"}, {"label": "Вес готового", "value": "~390 г"}], "total": {"label": "На весь бокал (~390 г) 1 порция", "kcal": 368.0, "macros": [{"label": "Белки", "value": 34.9}, {"label": "Жиры", "value": 9.6}, {"label": "Углеводы", "value": 37.6}]}, "per100": {"label": "На 100 г коктейля Плотность нутриентов", "kcal": 94.4, "macros": [{"label": "Белки", "value": 8.9}, {"label": "Жиры", "value": 2.4}, {"label": "Углеводы", "value": 9.6}]}, "ingredients": [{"name": "Молоко 2.5% (охлажденное)", "amount": "250 мл"}, {"name": "Спелый банан", "amount": "1 шт. (~100 г)"}, {"name": "Сывороточный протеин КСБ 80", "amount": "30 г (1 скуп)"}, {"name": "Какао «Золотой Ярлык»", "amount": "10–12 г (1 ст. л. с горкой)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "1–2 стика (по вкусу)"}, {"name": "Корица или ванилин", "amount": "щепотка (по желанию)"}], "steps": [{"title": "Подготовка шейкера и молоко первым", "html": "<div class=\"step-content\">\n<p>Возьмите чистый шейкер, <strong>выньте из него сетку и пружинный шарик</strong> (чтобы не задеть их ножами блендера). Налейте на дно <strong>250 мл холодного молока 2.5%</strong>. Наливать молоко первым обязательно, чтобы сухие порошки не налипли на сухое дно.</p>\n</div>"}, {"title": "Закладка банана и сухих компонентов", "html": "<div class=\"step-content\">\n<p>Очистите банан, разломите его руками на 3–4 части и опустите в молоко. Сверху добавьте <strong>30 г сывороточного протеина</strong>, <strong>1 ст. л. какао «Золотой Ярлык»</strong> и <strong>1–2 стика ФитПарада</strong>.</p>\n</div>"}, {"title": "Взбивание погружным блендером (30 секунд)", "html": "<div class=\"step-content\">\n<p>Опустите ножку погружного блендера прямо в шейкер до самого дна. Включите среднюю скорость и взбивайте <strong>25–35 секунд</strong> круговыми и приподнимающими движениями. Банан полностью разобьется в крем, а молоко с протеином взобьется в густую бархатистую пену.</p>\n</div>"}, {"title": "Подача и наслаждение", "html": "<div class=\"step-content\">\n<p>Коктейль готов! Пейте прямо из шейкера (ноль лишней грязной посуды) или перелейте в высокий стеклянный бокал с трубочкой. Сверху можно присыпать щепоткой какао или корицы.</p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card\">\n<h3>💡 Секреты идеального белкового милкшейка</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🥤 Взбивание в шейкере</strong>\n<p>Высокие стенки спортивного шейкера отлично защищают кухню от брызг. Главное — вынуть пружинку и пластиковую сеточку перед опусканием блендера.</p>\n</div>\n<div class=\"tip-box\">\n<strong>❄️ Лайфхак с замороженным бананом</strong>\n<p>Если нарезать банан кружочками и заморозить на 30–60 минут, милкшейк получится ледяным и настолько густым, как настоящее сливочное мягкое мороженое!</p>\n</div>\n<div class=\"tip-box\">\n<strong>⚡ Идеальное закрытие окна</strong>\n<p>Сочетание быстрого сывороточного протеина (24 г) и легкоусвояемых углеводов спелого банана максимально быстро запускает синтез мышечного белка после тренировки.</p>\n</div>\n</div>\n</div>"}, {"slug": "chocolate-greek-yogurt.html", "title": "Шоколадный греческий крем-десерт", "shortTitle": "Шоколадный греческий десерт", "description": "Нежнейший сливочно-шоколадный десерт со вкусом пломбира «Страчателла» или шоколадного пудинга. Густой греческий йогурт Простоквашино 235 г (8.7% белка!), 1 стик ФитПарада и шоколадный топпинг Bombbar без сахара. Ноль посуды и почти 21 г чистого белка за 30 секунд!", "image": "chocolate-greek-yogurt.png", "time": "30 секунд", "difficulty": "Простая", "tags": ["Без добавленного сахара", "До 20 мин"], "category": "Завтраки", "defaultVariant": 1, "variants": [{"id": 1, "name": "Оригинальный рецепт", "baseServings": 1, "meta": [{"label": "Время готовки", "value": "30 секунд"}, {"label": "Сложность", "value": "Проще простого"}, {"label": "Вес порции", "value": "~250 г"}, {"label": "Добавленный сахар", "value": "0 г"}], "total": {"label": "На всю порцию (~250 г) 1 баночка", "kcal": 158.0, "macros": [{"label": "Белки", "value": 20.8}, {"label": "Жиры", "value": 5.0}, {"label": "Углеводы", "value": 6.7}]}, "per100": {"label": "На 100 г десерта Легкий перекус", "kcal": 63.0, "macros": [{"label": "Белки", "value": 8.3}, {"label": "Жиры", "value": 2.0}, {"label": "Углеводы", "value": 2.7}]}, "ingredients": [{"name": "Греческий йогурт «Простоквашино» 2%", "amount": "235 г (1 баночка)"}, {"name": "Шоколадный топпинг Bombbar (без сахара)", "amount": "15–20 г (1–2 ч. л.)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "1 стик"}, {"name": "Ягоды или какао для подачи", "amount": "по желанию"}], "steps": [{"title": "Основа и сладость", "html": "<div class=\"step-content\">\n<p>Откройте баночку греческого йогурта «Простоквашино» (235 г). Всыпьте <strong>1 стик ФитПарада</strong> прямо в баночку (или переложите йогурт в красивую креманку) и аккуратно перемешайте ложкой до растворения подсластителя.</p>\n</div>"}, {"title": "Шоколадный акцент Bombbar", "html": "<div class=\"step-content\">\n<p>Выдавите поверх йогурта <strong>15–20 г шоколадного топпинга Bombbar</strong>. Натуральное какао в составе топпинга придаст глубокий благородный вкус темного шоколада без добавления лишних калорий.</p>\n</div>"}, {"title": "Два варианта подачи", "html": "<div class=\"step-content\">\n<p>\n<strong>Вариант «Страчателла» (рекомендуется):</strong> сделайте ложкой 2–3 легких круговых движения, чтобы получить красивый шоколадно-мраморный узор с контрастными сливочными и шоколадными слоями.<br/>\n<strong>Вариант «Шоколадный мусс»:</strong> полностью вымешайте топпинг с йогуртом до однородного кремового шоколадного цвета.\n                            </p>\n</div>"}]}], "extraHtml": "<div class=\"tips-card\">\n<h3>💡 Секреты идеального десерта</h3>\n<div class=\"tips-grid\">\n<div class=\"tip-box\">\n<strong>🍫 Сила топпинга Bombbar</strong>\n<p>Низкокалорийный топпинг Bombbar сделан на основе воды, какао-порошка и растворимых пищевых волокон. Порция топпинга дает всего ~10 ккал, но обеспечивает вкус настоящего растопленного шоколада.</p>\n</div>\n<div class=\"tip-box\">\n<strong>❄️ Эффект мягкого джелато</strong>\n<p>Поставьте готовую креманку в морозилку ровно на 15–20 минут перед употреблением. Йогурт подмерзнет у краев и превратится в густое сливочное шоколадное мороженое!</p>\n</div>\n<div class=\"tip-box\">\n<strong>🌙 Идеально перед сном</strong>\n<p>Греческий йогурт богат медленным белком (мицеллярным казеином). Он питает мышцы аминокислотами всю ночь и напрочь отбивает вечернюю тягу к сладкому.</p>\n</div>\n<div class=\"tip-box\">\n<strong>🫐 Дополнительные акценты</strong>\n<p>По желанию десерт можно посыпать щепоткой дробленого миндаля, гранолой без сахара или украсить горстью свежих ягод малины или черники.</p>\n</div>\n</div>\n</div>"}, {"slug": "caramel-cheesecake.html", "title": "Карамельно-сливочный ПП-чизкейк (1 кг)", "shortTitle": "Карамельный чизкейк (1 кг)", "description": "Высокий, плотный и шелковистый белковый чизкейк весом ровно 1 кг на брикетном твороге 0% и вареной сгущенке 4%. Без муки, масла и сахара. Рекордные 136 г белка на замес!", "image": "caramel-cheesecake-hero.jpg", "time": "40–45 минут", "difficulty": "Простая", "tags": ["Высокобелковое", "Без сахара"], "category": "Десерты", "defaultVariant": 1, "variants": [{"id": 1, "name": "Карамельный крем-брюле (вареная сгущенка 4%)", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "40–45 мин (духовка) / 30–35 мин (аэрогриль)"}, {"label": "Температура", "value": "175–180°C (духовка) / 160°C (аэрогриль)"}, {"label": "Порций", "value": "4 порции"}, {"label": "Сырой замес", "value": "1 000 грамм (1 кг)"}], "total": {"label": "На весь чизкейк Вес ~1 000 г сырого замеса", "kcal": 1415.0, "macros": [{"label": "Белки", "value": 136.0}, {"label": "Жиры", "value": 33.0}, {"label": "Углеводы", "value": 147.0}]}, "per100": {"label": "На 100 г чизкейка", "kcal": 141.5, "macros": [{"label": "Белки", "value": 13.6}, {"label": "Жиры", "value": 3.3}, {"label": "Углеводы", "value": 14.7}]}, "ingredients": [{"name": "Творог «Красная цена» обезжиренный 0%", "amount": "540 г (3 пачки по 180 г)"}, {"name": "Яйца куриные С0 (крупные)", "amount": "4 шт (~240 г без скорлупы)"}, {"name": "Вареная сгущенка 4%", "amount": "220 г (~0.6 банки)"}, {"name": "Ванилин", "amount": "1 пакетик (1–1.5 г)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "1–2 стика (по вкусу)"}], "steps": [{"title": "Подготовка и соединение ингредиентов", "html": "<div class=\"step-content\"><p>В глубокую миску или чашу для взбивания выложите <strong>3 пачки творога «Красная цена» 0% (540 г)</strong>, разбейте <strong>4 крупных яйца С0</strong>, отмерьте на кухонных весах ровно <strong>220 г вареной сгущенки 4%</strong>, всыпьте 1 пакетик ванилина и 1–2 стика ФитПарада для десертной сладости.</p><div class=\"step-img-box\"><img src=\"caramel-cheesecake-step-mix.jpg\" alt=\"Ингредиенты в чаше перед взбиванием\" loading=\"lazy\"></div></div>"}, {"title": "Взбивание блендером (секрет шелковистости)", "html": "<div class=\"step-content\"><p>Творог «Красная цена» плотный и брикетный, поэтому вилкой или венчиком его не размешать. Погружным блендером тщательно пробивайте массу <strong>2–3 минуты круговыми движениями</strong>, пока крупинки творога и густая варенка не превратятся в абсолютно гладкий, глянцевый карамельный крем цвета вареного сгущенного молока.</p><div class=\"step-img-box\"><img src=\"caramel-cheesecake-step-blend.jpg\" alt=\"Шелковистый карамельный крем после блендера\" loading=\"lazy\"></div></div>"}, {"title": "Подготовка формы (16–18 см)", "html": "<div class=\"step-content\"><p>Для такого объема (1 кг массы) идеальна форма диаметром <strong>16–18 см</strong> — чизкейк получится высоким и красивым. Если используете металлическую разъемную форму, застелите дно пергаментом, а бортики смажьте каплей масла. Если форма силиконовая — можно выливать крем сразу.</p></div>"}, {"title": "Выпекание (в духовке или аэрогриле)", "html": "<div class=\"step-content\"><p><strong>В духовке:</strong> разогрейте духовку до <strong>175–180°C</strong>. Выпекайте на среднем уровне <strong>40–45 минут</strong>. Верх схватится и красиво подрумянится, а серединка при покачивании формы может слегка подрагивать (это нормально для нежного творожного суфле).</p><p><strong>В аэрогриле:</strong> выпекайте при <strong>160°C в течение 30–35 минут</strong>. Первые 20 минут обязательно прикройте форму сверху фольгой, чтобы верх не подгорел от близкого ТЭНа, затем снимите фольгу на оставшиеся 10–12 минут для золотистой корочки.</p><div class=\"step-img-box\"><img src=\"caramel-cheesecake-step-oven.jpg\" alt=\"Выпекание чизкейка в форме\" loading=\"lazy\"></div></div>"}, {"title": "Охлаждение и стабилизация в холоде", "html": "<div class=\"step-content\"><p>Не нарезайте чизкейк горячим! Дайте ему остыть прямо в форме при комнатной температуре около 1 часа, затем <strong>уберите в холодильник минимум на 2–3 часа (а лучше на ночь)</strong>. Молочный и яичный белок стабилизируются, текстура станет плотной, монолитной и тающей во рту, как настоящее крем-брюле.</p></div>"}]}, {"id": 2, "name": "Сливочный пломбир (светлая сгущенка 1%)", "baseServings": 4, "meta": [{"label": "Время готовки", "value": "40–45 мин (духовка) / 30–35 мин (аэрогриль)"}, {"label": "Температура", "value": "175–180°C (духовка) / 160°C (аэрогриль)"}, {"label": "Порций", "value": "4 порции"}, {"label": "Сырой замес", "value": "1 000 грамм (1 кг)"}], "total": {"label": "На весь чизкейк Вес ~1 000 г сырого замеса", "kcal": 1415.0, "macros": [{"label": "Белки", "value": 138.0}, {"label": "Жиры", "value": 26.4}, {"label": "Углеводы", "value": 156.0}]}, "per100": {"label": "На 100 г чизкейка", "kcal": 141.5, "macros": [{"label": "Белки", "value": 13.8}, {"label": "Жиры", "value": 2.6}, {"label": "Углеводы", "value": 15.6}]}, "ingredients": [{"name": "Творог «Красная цена» обезжиренный 0%", "amount": "540 г (3 пачки по 180 г)"}, {"name": "Яйца куриные С0 (крупные)", "amount": "4 шт (~240 г без скорлупы)"}, {"name": "Сгущенное молоко светлое 1%", "amount": "220 г (~0.6 банки)"}, {"name": "Ванилин", "amount": "1 пакетик (1–1.5 г)"}, {"name": "Заменитель сахара (ФитПарад)", "amount": "1–2 стика (по вкусу)"}], "steps": [{"title": "Подготовка и соединение ингредиентов", "html": "<div class=\"step-content\"><p>В глубокую миску или чашу для взбивания выложите <strong>3 пачки творога «Красная цена» 0% (540 г)</strong>, разбейте <strong>4 крупных яйца С0</strong>, отмерьте на весах ровно <strong>220 г светлой сгущенки 1%</strong>, всыпьте 1 пакетик ванилина и 1–2 стика ФитПарада для насыщенного пломбирного вкуса.</p><div class=\"step-img-box\"><img src=\"caramel-cheesecake-step-mix.jpg\" alt=\"Ингредиенты в чаше перед взбиванием\" loading=\"lazy\"></div></div>"}, {"title": "Взбивание блендером до пломбирного крема", "html": "<div class=\"step-content\"><p>Погружным блендером тщательно пробивайте массу <strong>2–3 минуты круговыми движениями</strong>. Плотный брикетный творог соединится со светлой сгущенкой в гладкую, шелковистую белоснежную эмульсию без крупинок, напоминающую растаявшее мороженое пломбир.</p><div class=\"step-img-box\"><img src=\"caramel-cheesecake-step-blend.jpg\" alt=\"Шелковистый крем после блендера\" loading=\"lazy\"></div></div>"}, {"title": "Подготовка формы (16–18 см)", "html": "<div class=\"step-content\"><p>Используйте форму диаметром <strong>16–18 см</strong> — чизкейк получится пышным и высоким. Застелите дно пергаментной бумагой, а бортики смажьте каплей масла (силиконовую форму можно использовать без смазывания). Аккуратно перелейте творожно-пломбирную массу.</p></div>"}, {"title": "Выпекание (в духовке или аэрогриле)", "html": "<div class=\"step-content\"><p><strong>В духовке:</strong> разогрейте духовку до <strong>175–180°C</strong> и выпекайте на среднем уровне <strong>40–45 минут</strong>. Верхушка станет приятно золотистой, а серединка при легком встряхивании формы будет слегка подрагивать.</p><p><strong>В аэрогриле:</strong> выпекайте при <strong>160°C в течение 30–35 минут</strong>. Первые 20 минут обязательно держите форму накрытой фольгой, а за 10–12 минут до конца снимите фольгу для нежного аппетитного колера.</p><div class=\"step-img-box\"><img src=\"caramel-cheesecake-step-oven.jpg\" alt=\"Выпекание чизкейка в форме\" loading=\"lazy\"></div></div>"}, {"title": "Охлаждение и стабилизация в холодильнике", "html": "<div class=\"step-content\"><p>Дайте чизкейку остыть до комнатной температуры прямо в форме (~1 час), а затем <strong>уберите в холодильник минимум на 2–3 часа (лучше на ночь)</strong>. Творог и яичный белок окончательно схватятся в упругий, нежнейший десерт со сливочно-пломбирным вкусом и минимальным жиром (всего 2.6 г на 100 г!).</p></div>"}]}], "extraHtml": "<div class=\"tips-card\"><h3>💡 Секреты идеального результата</h3><div class=\"tips-grid\"><div class=\"tip-box\"><strong>🍮 Настоящее крем-брюле</strong><p>Вареная сгущенка 4% придает глубокий вкус томленого молока и ириски без необходимости использовать жирные сливки или масло.</p></div><div class=\"tip-box\"><strong>🌀 Только погружной блендер</strong><p>2–3 минуты работы блендером разбивают плотные творожные крупинки в шелковистую ресторанную эмульсию.</p></div><div class=\"tip-box\"><strong>❄️ Ночь в холодильнике</strong><p>После выпекания чизкейк мягкий, но после охлаждения режется идеальными четкими треугольниками.</p></div></div></div>"}, {"slug": "lentil-apple-cake.html", "title": "Сладкий чечевичный кекс с яблоком и изюмом", "shortTitle": "Сладкий чечевичный кекс", "description": "Пышный, сытный и ароматный десертный кекс-лепешка на замоченной красной чечевице с бананом, свежим яблоком и изюмом. Без пшеничной муки, рафинированного масла и добавленного сахара. Рекордный растительный протеин и долгая сытость!", "image": "lentil-apple-cake.jpg", "time": "50 минут", "difficulty": "Простая", "tags": ["Высокобелковое", "Без сахара"], "category": "Выпечка", "defaultVariant": 1, "variants": [{"id": 1, "name": "Пряный фруктовый (большая лепешка на противне)", "baseServings": 8, "meta": [{"label": "Время готовки", "value": "50 минут"}, {"label": "Температура", "value": "180°C"}, {"label": "Порций", "value": "8 порций"}, {"label": "Готовый вес", "value": "~1 120 грамм"}], "total": {"label": "На весь кекс Вес ~1 120 г готового", "kcal": 3136.0, "macros": [{"label": "Белки", "value": 154.0}, {"label": "Жиры", "value": 20.7}, {"label": "Углеводы", "value": 605.0}]}, "per100": {"label": "На 100 г готового кекса", "kcal": 280.0, "macros": [{"label": "Белки", "value": 13.8}, {"label": "Жиры", "value": 1.85}, {"label": "Углеводы", "value": 54.0}]}, "ingredients": [{"name": "Красная чечевица (сухой вес)", "amount": "566 г (замочить на 2–3 часа)"}, {"name": "Тёмный изюм", "amount": "300 г (замочить на 10–15 мин)"}, {"name": "Яблоко свежее (очищенное)", "amount": "246 г"}, {"name": "Банан спелый", "amount": "129 г (1 шт)"}, {"name": "Куриные яйца С0/С1", "amount": "3 шт"}, {"name": "Псиллиум (шелуха подорожника)", "amount": "6 ч. л. (~20–24 г)"}, {"name": "Разрыхлитель теста", "amount": "5 г (1 ч. л.)"}, {"name": "Соль мелкая", "amount": "3 г (щепотка, подчеркнет сладость)"}], "steps": [{"title": "Замачивание чечевицы и изюма", "html": "<div class=\"step-content\"><p>Красную чечевицу (566 г) тщательно промойте в холодной воде и <strong>замочите на 2–3 часа</strong> (она набухнет и станет мягкой). Тёмный изюм (300 г) промойте и залейте теплой водой на <strong>10–15 минут</strong>, затем слейте воду и обсушите салфеткой.</p></div>"}, {"title": "Приготовление фруктово-чечевичного пюре", "html": "<div class=\"step-content\"><p>С чечевицы полностью слейте воду. Переложите размоченную чечевицу в чашу комбайна или глубокую емкость для блендера. Добавьте 3 яйца, поломанный на кусочки банан (129 г), нарезанное яблоко (246 г) и 3 г соли. Тщательно пробейте блендером <strong>до однородного гладкого пюре</strong>.</p></div>"}, {"title": "Введение псиллиума и отдых теста (7–10 минут)", "html": "<div class=\"step-content\"><p>В полученное пюре всыпьте <strong>6 ч. л. псиллиума</strong> и 5 г разрыхлителя. Перемешайте силиконовой лопаткой и <strong>оставьте на 7–10 минут</strong>. Псиллиум впитает свободную влагу фруктов и чечевицы, превратив массу в пышное и податливое кексовое тесто.</p></div>"}, {"title": "Вмешивание сочного изюма", "html": "<div class=\"step-content\"><p>В загустевшее тесто добавьте обсушенный тёмный изюм и аккуратно перемешайте лопаткой, равномерно распределяя ягодки по всему объему.</p></div>"}, {"title": "Формовка и выпекание (180°C, ~50 минут)", "html": "<div class=\"step-content\"><p>Противень застелите качественным силиконизированным пергаментом. Выложите тесто и разровняйте лопаткой в виде <strong>большой круглой или овальной лепешки-коврижки</strong> толщиной около 2–3 см (или выложите в прямоугольную форму для кекса). Разогрейте духовку до <strong>180°C</strong> и выпекайте около <strong>50 минут</strong>. Готовность проверьте деревянной шпажкой — она должна выходить сухой.</p></div>"}, {"title": "Остывание и подача", "html": "<div class=\"step-content\"><p>Дайте кексу полностью остыть на решетке. При остывании текстура стабилизируется, станет мягкой, мелкопористой и слегка влажной, как традиционная рождественская коврижка. Нарежьте на порционные кусочки.</p></div>"}]}], "extraHtml": "<div class=\"tips-card\"><h3>💡 Секреты идеального результата</h3><div class=\"tips-grid\"><div class=\"tip-box\"><strong>🌾 Сила красной чечевицы</strong><p>Красная чечевица нейтральна на вкус и после блендера дает шелковистую бисквитную структуру без привкуса бобовых, обеспечивая почти 14 г белка на 100 г.</p></div><div class=\"tip-box\"><strong>🍯 Естественная сладость</strong><p>Банан, яблоко и сочный тёмный изюм дают достаточную десертную сладость — добавленный сахар или сиропы не требуются.</p></div><div class=\"tip-box\"><strong>🌱 Роль псиллиума</strong><p>Шелуха подорожника скрепляет безглютеновое тесто, не давая лепешке крошиться или расползаться на противне.</p></div></div></div>"}, {"slug": "cottage-cheese-baked-apples.html", "title": "Творожный крем с печёными яблоками и цветочным мёдом", "shortTitle": "Творожный крем с печёными яблоками", "description": "Прохладный творожный крем с тёплыми яблоками из аэрогриля и ароматным цветочным мёдом. Высокобелковый десерт без муки и сахара-песка, с мёдом и подсластителем. Результат приготовления на оценке.", "image": "cottage-cheese-baked-apples.jpg", "time": "около 25 минут", "difficulty": "Простая", "tags": ["Высокобелковое"], "category": "Десерты", "defaultVariant": 1, "variants": [{"id": 1, "name": "Классический в аэрогриле (на оценке)", "baseServings": 2, "meta": [{"label": "Время готовки", "value": "около 25 минут"}, {"label": "Температура", "value": "170°C (аэрогриль)"}, {"label": "Порций", "value": "2 большие порции"}, {"label": "Оборудование", "value": "Аэрогриль, пергамент, блендер"}], "total": {"label": "На весь десерт (2 порции)", "kcal": 800.0, "macros": [{"label": "Белки", "value": 74.2}, {"label": "Жиры", "value": 23.2}, {"label": "Углеводы", "value": 71.6}]}, "per100": {"label": "На 100 г готового (ориентировочно)", "kcal": 105.0, "macros": [{"label": "Белки", "value": 9.7}, {"label": "Жиры", "value": 3.0}, {"label": "Углеводы", "value": 9.4}]}, "ingredients": [{"name": "Творог «Першино» 5%", "amount": "380 г"}, {"name": "Греческий йогурт TEOS натуральный 2%", "amount": "150 г"}, {"name": "Яблоки без сердцевины (кубиками 1.5–2 см)", "amount": "300 г (кожуру можно оставить)"}, {"name": "Цветочный мёд", "amount": "30 г (15 г в крем, 15 г для подачи)"}, {"name": "ФитПарад №10", "amount": "4 стика (по вкусу)"}, {"name": "Корица молотая", "amount": "щепотка (по желанию)"}, {"name": "Вода питьевая", "amount": "10–15 г (только при необходимости)"}], "steps": [{"title": "Подготовить яблоки", "html": "<div class=\"step-content\"><p>Вымыть яблоки, удалить сердцевины и отвесить <strong>300 г съедобной части</strong>. Нарезать аккуратными кубиками размером 1,5–2 см (кожуру можно оставить для текстуры и аромата).</p></div>"}, {"title": "Выложить на пергамент в аэрогриле", "html": "<div class=\"step-content\"><p>Дно корзины аэрогриля застелить листом пергамента (с небольшими бортиками, чтобы сохранить весь яблочный сок). Равномерно распределить нарезанные яблоки в один слой. При желании посыпать небольшой щепоткой молотой корицы. <em>Масло, мёд и ФитПарад к яблокам не добавлять.</em></p></div>"}, {"title": "Запечь на пергаменте (170°C, 12–18 мин)", "html": "<div class=\"step-content\"><p>Готовить в аэрогриле при <strong>170°C примерно 12–18 минут</strong> прямо на пергаменте. Через 8–10 минут аккуратно перемешать лопаткой и проверить мягкость. Готовые яблоки должны легко прокалываться вилкой. Время зависит от сорта яблок и размера кусочков. Пергамент защитит корзину от пригорания и сохранит ароматный карамельный сок.</p></div>"}, {"title": "Сделать прохладный творожный крем", "html": "<div class=\"step-content\"><p>В глубокой емкости соединить: <strong>380 г творога «Першино» 5%</strong>, <strong>150 г йогурта TEOS 2%</strong>, <strong>15 г цветочного мёда</strong> и <strong>4 стика ФитПарада №10</strong>. Тщательно пробить погружным блендером до абсолютно однородной, гладкой шелковистой консистенции. <em>(Без блендера можно размять вилкой, но текстура останется зернистой).</em></p></div>"}, {"title": "Немного остудить яблоки", "html": "<div class=\"step-content\"><p>После запекания дать яблокам постоять на пергаменте несколько минут: они должны стать приятно тёплыми, а не обжигающе горячими, чтобы не растопить структуру прохладного творожного крема.</p></div>"}, {"title": "Собрать две порции", "html": "<div class=\"step-content\"><p>Разделить прохладный крем поровну между двумя глубокими креманками или мисками. Сверху выложить тёплые яблоки, аккуратно перелив с пергамента весь выделившийся при запекании сок. Полить каждую порцию <strong>7,5 г мёда</strong>.</p></div>"}, {"title": "Подача и дегустация", "html": "<div class=\"step-content\"><p>Подавать сразу для выразительного контраста прохладного шелковистого крема и нежных пряных тёплых яблок. Также десерт можно полностью охладить в холодильнике и подавать как освежающий холодный крем.</p></div>"}]}], "extraHtml": "<div class=\"tips-card\"><h3>💡 Важные примечания и основа расчёта</h3><div class=\"tips-grid\"><div class=\"tip-box\"><strong>⚖️ Статус: На оценке</strong><p>Рецепт добавлен как экспериментальный. Результат приготовления ещё не оценён, поэтому отметка проверенного рецепта пока не присвоена.</p></div><div class=\"tip-box\"><strong>🍯 Сладость и сахара</strong><p>4 стика ФитПарада №10 вместе с мёдом дают сбалансированную десертную сладость (1 стик равен ~2 ч. л. сахара). Количество можно регулировать по вкусу. Метка «без сахара» не присвоена из-за природных сахаров мёда и яблок.</p></div><div class=\"tip-box\"><strong>📊 Ориентировочное КБЖУ</strong><p>На весь десерт: ~800 ккал, Б 74.2 г, Ж 23.2 г, У 71.6 г (на порцию: ~400 ккал, Б 37.1 г, Ж 11.6 г, У 35.8 г). КБЖУ на 100 г ориентировочное (~105 ккал при готовом весе ~760 г с учётом усушки).</p></div></div></div>"}];
